 const base=byStage(appBase).filter(x=>ctx.id&&sameLesson(x,ctx.id));
 const groups=uniq(base.map(x=>A.dialogueGroup?.(x)||x.group||x.applicationDomain||'ứng dụng'));
 const diffs=uniq(base.map(x=>A.dialogueDifficulty?.(x)||x.difficulty||x.level||'applied'));
 if(state.practiceGroup!=='all'&&!groups.includes(state.practiceGroup))state.practiceGroup='all';
