function mathDeptInfoFromLesson(l){
 const st=stageOf(l)||state.stage||'vn';
 const title=lower([l?.departmentTitle,l?.moduleTitle,l?.clusterTitle,l?.chapterTitle,l?.title,l?.id].filter(Boolean).join(' '));
 const label=str(l?.moduleTitle||l?.clusterTitle||l?.chapterTitle||l?.title||'Bài giảng');
 let facultyId='faculty_foundation',facultyTitle='Khoa Toán nền tảng',facultySub='Đại số, giải tích, xác suất, tín hiệu nền cho AI';
 if(st==='prep'){facultyId='faculty_prep';facultyTitle='Khoa Toán dự bị Nga/STANKIN';facultySub='Toán kỹ thuật và thuật ngữ học thuật trước Bauman';}
 if(st==='hk1'){facultyId='faculty_bauman_core';facultyTitle='Khoa Toán lõi Bauman';facultySub='Toán chính khóa cho mô hình hóa, tối ưu và xử lý dữ liệu';}
 if(st==='hk3'){facultyId='faculty_research';facultyTitle='Khoa Toán nghiên cứu НИР';facultySub='Toán cho robot, tín hiệu, Kalman, đồ thị và đánh giá mô hình';}
 if(st==='hk4'){facultyId='faculty_vkr';facultyTitle='Khoa Toán luận văn ВКР';facultySub='Toán cho bảo vệ, phản biện và báo cáo kết quả';}
 let deptId='dept_general',deptTitle='Bộ môn Toán nền tảng',deptSub='Các mục lý thuyết cần học theo chương',deptIcon='∑';
 const has=(...keys)=>keys.some(k=>title.includes(k));
 if(has('vector','ma trận','hệ tuyến','tuyến tính','trị riêng','svd','pca','hiệp phương sai','tương quan')){deptId='dept_linear_data';deptTitle='Bộ môn Đại số tuyến tính & biểu diễn dữ liệu';deptSub='Vector, ma trận, hạng, nghiệm hệ, PCA/SVD';deptIcon='▦';}
 else if(has('đạo hàm','gradient','hessian','jacobian','tối ưu','giải tích','liên tục')){deptId='dept_calculus_optim';deptTitle='Bộ môn Giải tích & tối ưu hóa';deptSub='Đạo hàm, gradient, Hessian, hội tụ và cực trị';deptIcon='∇';}
 else if(has('xác suất','bayes','ngẫu nhiên','kỳ vọng','phương sai','thống kê','khoảng tin cậy','ước lượng')){deptId='dept_probability_stats';deptTitle='Bộ môn Xác suất, thống kê & suy luận dữ liệu';deptSub='Bayes, biến ngẫu nhiên, ước lượng, kiểm định';deptIcon='P';}
 else if(has('chuỗi thời gian','fourier','laplace','tín hiệu','lọc','phổ','nhiễu')){deptId='dept_signal_time';deptTitle='Bộ môn Tín hiệu & chuỗi thời gian';deptSub='Fourier, lọc, phổ, nhiễu, dự báo';deptIcon='≈';}
 else if(has('phương trình vi phân','ode','động lực','ổn định','điều khiển')){deptId='dept_dynamics_control';deptTitle='Bộ môn Mô hình động lực & điều khiển';deptSub='ODE, ổn định, mô hình trạng thái, điều khiển';deptIcon='ẋ';}
 else if(has('số','sai số','điều kiện','condition','xấp xỉ','nội suy','thuật toán')){deptId='dept_numerical';deptTitle='Bộ môn Tính toán số & ổn định thuật toán';deptSub='Sai số, điều kiện, thuật toán lặp, kiểm chứng số';deptIcon='μ';}
 else if(has('robot','kalman','đồ thị','graph','nir','vkr','luận văn','bảo vệ')){deptId='dept_research_methods';deptTitle='Bộ môn Toán nghiên cứu, robot & luận văn';deptSub='Kalman, đồ thị, chỉ số đánh giá, phản biện VKR';deptIcon='R';}
 return {stage:st,facultyId:facultyId+'_'+st,facultyTitle,facultySub,deptId:facultyId+'_'+deptId,deptTitle,deptSub,deptIcon,chapterTitle:label};
}











