function simRangeHtml(v,i){
 const min=Number(v?.min??0), max=Number(v?.max??100), def=Number(v?.default??50); const pct=max>min?Math.round((def-min)*100/(max-min)):def;
 return `<article class="mathlab-var-card" style="--p:${Math.max(0,Math.min(100,pct))}%"><label>${esc(v?.label||v?.name||('Biến '+(i+1)))}</label><div class="range-shell"><i class="range-fill" style="width:${Math.max(0,Math.min(100,pct))}%"></i><input class="mathlab-range" type="range" min="${esc(min)}" max="${esc(max)}" value="${esc(def)}" oninput="this.previousElementSibling.style.width=((this.value-this.min)*100/(this.max-this.min))+'%'; this.closest('article').querySelector('output').textContent=this.value"></div><small>min ${esc(min)} · default <output>${esc(def)}</output> · max ${esc(max)}</small><p>${esc(v?.effect||'Đổi biến và quan sát đầu ra.')}</p></article>`;
}



