function v33ItemKey(item){return str(item?.lessonId||item?.targetId||item?.id||item?.title||'');}
function v33LessonById(id){return arr(DB.lessons).find(l=>str(l.lessonId||l.id)===str(id))||{};}
function v33ChapterNo(title,id){
 const s=str(title||id||'');
 const m=s.match(/(?:Chương|CHƯƠNG)\s*([0-9IVXLC]+)/i)||s.match(/C(\d{2})/i);
 return m?m[1]:'';
}
function v33SectionNo(title,id){
 const s=str(title||id||'');
 const m=s.match(/§\s*([0-9]+(?:\.[0-9]+)?)/)||s.match(/L(\d{2})/i);
 return m?m[1]:'';
}
function v33ResourceMeta(item){
 const lesson=v33LessonById(item?.lessonId||item?.targetId||item?.id);
 const merged=Object.assign({},lesson,item||{});
 const m=mathDeptInfoFromLesson(merged);
 const stage=stageOf(merged)||m.stage||state.stage||'vn';
 const chapterId=str(merged.chapterId||lesson.chapterId||('chapter_'+(merged.sourceChapterId||merged.moduleId||m.chapterTitle||'general')));
 const chapterTitle=str(merged.chapterTitle||lesson.chapterTitle||m.chapterTitle||'Chương nội dung');
 return Object.assign({},m,{stage,chapterId,chapterTitle,chapterNo:v33ChapterNo(chapterTitle,chapterId)});
}
function v33GroupedTree(records, activeItem, cfg={}){
 const list=arr(records);
 if(!list.length)return `<div class="note v33-empty-note">${esc(cfg.empty||'Chưa có dữ liệu phù hợp.')}</div>`;
 const activeKey=cfg.activeKey?cfg.activeKey(activeItem):v33ItemKey(activeItem||{});
 const root=new Map();
 list.forEach((item,idx)=>{
  const meta=v33ResourceMeta(item);
  const fKey=meta.facultyId||('faculty_'+meta.stage), dKey=meta.deptId||'dept_general', cKey=meta.chapterId||'chapter_general';
  if(!root.has(fKey))root.set(fKey,{meta,items:[],depts:new Map()});
  const f=root.get(fKey); f.items.push(item);
  if(!f.depts.has(dKey))f.depts.set(dKey,{meta,items:[],chapters:new Map()});
  const d=f.depts.get(dKey); d.items.push(item);
  if(!d.chapters.has(cKey))d.chapters.set(cKey,{meta,items:[]});
  d.chapters.get(cKey).items.push({item,idx});
 });
 const itemButton=(it,j)=>{
  const item=it.item, idx=it.idx;
  const key=cfg.activeKey?cfg.activeKey(item):v33ItemKey(item);
  const active=key===activeKey || (cfg.activeItem && cfg.activeItem(item,idx));
  const title=cfg.title?cfg.title(item,idx):str(item.displayTitle||item.title||item.question||item.id||'Mục học');
  const sub=cfg.sub?cfg.sub(item,idx):str(item.lessonId||item.chapterId||item.stage||'');
  const attrs=cfg.attrs?cfg.attrs(item,idx):`data-resource-key="${esc(key)}"`;
  const no=cfg.number?cfg.number(item,idx,j):String(j+1).padStart(2,'0');
  return `<button class="math-v33-choice ${active?'active':''}" ${attrs}><span>${esc(no)}</span><div><b>${esc(clip(title,86))}</b>${sub?`<small>${esc(clip(sub,112))}</small>`:''}</div></button>`;
 };
 const facultyHtml=Array.from(root.values()).map((f,fi)=>{
  const fActive=f.items.some(item=>(cfg.activeKey?cfg.activeKey(item):v33ItemKey(item))===activeKey);
  const deptHtml=Array.from(f.depts.values()).map((d,di)=>{
   const dActive=d.items.some(item=>(cfg.activeKey?cfg.activeKey(item):v33ItemKey(item))===activeKey);
   const chapterHtml=Array.from(d.chapters.values()).map((c,ci)=>{
    const cActive=c.items.some(it=>(cfg.activeKey?cfg.activeKey(it.item):v33ItemKey(it.item))===activeKey || (cfg.activeItem&&cfg.activeItem(it.item,it.idx)));
    const secCount=c.items.length;
    const chapterNo=c.meta.chapterNo?`Chương ${c.meta.chapterNo}`:'Chương';
    const rows=c.items.map(itemButton).join('');
    return `<details class="math-v33-chapter" ${cActive||(!dActive&&di===0&&ci===0&&fi===0)?'open':''}><summary class="math-v33-chapter-trigger"><span>${esc(chapterNo)}</span><b>${esc(c.meta.chapterTitle)}</b><i>${secCount} mục</i><u>▾</u></summary><div class="math-v33-section-list">${rows}</div></details>`;
   }).join('');
   return `<details class="math-v33-dept" ${dActive||(!fActive&&fi===0&&di===0)?'open':''}><summary class="math-v33-dept-trigger"><i>${esc(d.meta.deptIcon||'∑')}</i><div><b>${esc(d.meta.deptTitle)}</b><small>${esc(d.meta.deptSub||'Bộ môn trong Khoa Toán')}</small></div><em>${d.chapters.size} chương</em><u>▾</u></summary><div class="math-v33-chapter-stack">${chapterHtml}</div></details>`;
  }).join('');
  return `<details class="math-v33-faculty" ${fActive||fi===0?'open':''}><summary class="math-v33-faculty-trigger"><span class="math-v33-faculty-no">${String(fi+1).padStart(2,'0')}</span><div><b>${esc(f.meta.facultyTitle)}</b><small>${esc(stageTitle(f.meta.stage))} · ${esc(f.meta.facultySub||'')}</small></div><em>${f.depts.size} bộ môn</em><u>▾</u></summary><div class="math-v33-dept-stack">${deptHtml}</div></details>`;
 }).join('');
 return `<div class="math-v33-tree ${esc(cfg.className||'')}">${facultyHtml}</div>`;
}
function renderMathFacultyTheoryList(lessons,current){
 return v33GroupedTree(lessons,current,{className:'theory-tree',empty:'Chưa có bài giảng lý thuyết.',activeKey:l=>lessonKey(l||{}),attrs:(l)=>`data-lesson="${esc(lessonKey(l))}"`,title:l=>str(l.displayTitle||A.lessonTitle?.(l)||l.title||'Bài giảng'),sub:l=>str(l.shortTitle||l.chapterTitle||l.moduleTitle||''),number:l=>v33SectionNo(l.displayTitle||l.title,l.lessonId)||'§'});
}
