function getVocab(){
 let xs=Array.isArray(DB.formulas)&&DB.formulas.length?byStage(DB.formulas):byStage(call('getVocabulary',[],DB));
 if(state.vocabQuery)xs=xs.filter(x=>lower([x.id,x.title,x.formula,x.meaning,x.term,x.front,x.lessonId,x.chapterId,JSON.stringify(x.conceptIds||[]),JSON.stringify(x.tags||[])].join(' ')).includes(lower(state.vocabQuery)));
 return xs;
}
function v34FormulaInfo(item){
 const base=vocabInfo(item||{});
 const formula=str(item?.formula||item?.front||item?.term||base.term||'');
 const title=str(item?.title||item?.term||base.term||'Công thức');
 const meaning=str(item?.meaning||item?.definition||base.displayMeaning||base.meaningVi||base.english||'Công thức/ký hiệu cần nhớ trong chương này.');
 const conditions=arr(item?.conditions).length?arr(item.conditions):arr(item?.condition).length?arr(item.condition):[];
 const mistakes=arr(item?.commonMistakes).length?arr(item.commonMistakes):arr(item?.mistakes).length?arr(item.mistakes):[];
 const example=str(item?.example||item?.application||item?.usage||base.example||'');
 return {...base,formula,title,meaning,conditions,mistakes,example,term:formula||title,displayMeaning:meaning};
}
