function storageGroupFilterTabs(){
 const groups=storageGroups().map(g=>[g[0],g[1],g[0]]);
 if(!groups.some(g=>g[0]===state.storageGroup))state.storageGroup=groups[0]?.[0]||'Tổng quan';
 const active=state.storageGroup;
 const activeMeta=storageGroups().find(g=>g[0]===active)||['Tổng quan','🧭',[]];
 const activeFiles=(activeMeta[2]||[]).filter(f=>ALL_STORAGE_FILES.includes(f));
 const loaded=activeFiles.filter(f=>!!DB[f]).length;
 return `<div class="v38-data-groupbar" aria-label="Bộ chọn nhóm dữ liệu"><div class="v38-data-group-info"><span class="v38-data-dot">${esc(activeMeta[1])}</span><div><b>${esc(activeMeta[0])}</b><small>${loaded}/${activeFiles.length||0} nguồn đang có dữ liệu</small></div></div><details class="storage-group-menu v38-data-menu"><summary class="storage-group-trigger v38-data-trigger"><span>🗄️</span><b>Kho môn học</b><u>▾</u></summary><div class="storage-group-indicator v38-data-indicator"><i></i><span>${esc(activeMeta[0])} · ${loaded}/${activeFiles.length||0} nguồn</span></div><div class="storage-group-dropdown v38-data-dropdown" role="menu">${groups.map(([id,icon,label])=>`<button class="storage-group-choice ${active===id?'active':''}" data-storage-group="${esc(id)}"><span>${icon}</span><b>${esc(label)}</b></button>`).join('')}</div></details></div>`;
}
function storageAmmunitionShelf(){
 const visible=storageFilesForActiveGroup();
 const cards=visible.map(f=>storageArsenalFileCard(f).replace('class="arsenal-file-card','class="arsenal-file-card v38-data-source-card')).join('');
 return `<section class="panel v38-data-left"><header class="v38-data-left-head"><div class="v38-data-title"><span class="chip">FILE JSON</span><h3>Nguồn dữ liệu</h3><p>Chọn nguồn theo slot. Tên file chỉ là vỏ, slot mới là bản chất.</p></div>${storageGroupFilterTabs()}<input class="input v38-data-search" data-input="storageQuery" value="${esc(state.storageQuery||'')}" placeholder="Tìm file, tab dùng, stage, nội dung..."></header><div class="v38-data-source-list clean-scroll">${cards||'<article class="storage-empty"><b>Không có file phù hợp</b><span>Xóa từ khóa hoặc chọn nhóm khác.</span></article>'}</div></section>`;
}
function renderStorage(){
 const files=ALL_STORAGE_FILES;
 if(!files.includes(state.storageFile))state.storageFile=files[0];
 const groupNames=storageGroups().map(g=>g[0]); if(!groupNames.includes(state.storageGroup))state.storageGroup=groupNames[0]||'Tổng quan';
 const visible=storageFilesForActiveGroup(); if(visible.length&&!visible.includes(state.storageFile))state.storageFile=visible[0];
 const name=state.storageFile||files[0], data=DB[name];
 const status=sourceStatus(name,data), count=sourceCount(name,data), loaded=sourceLoadedCount(name,data), planned=sourcePlannedCount(name), lazyUnloaded=isOptionalFile(name)&&!data;
 const tools=lazyUnloaded?`<div class="v38-data-tools"><button class="btn primary" data-load-optional="${esc(name)}">Tải nguồn này</button><button class="btn" data-act="export-source-plan">Xuất mô tả nguồn</button></div>`:`<div class="v38-data-tools"><label class="btn primary">Nhập/Thay file<input id="storageImport" type="file" accept=".json,application/json" hidden></label><button class="btn" data-act="storage-add-item">＋ Thêm mục</button><button class="btn" data-act="export-source">Xuất nguồn</button><button class="btn" data-act="storage-reset-source">Khôi phục nguồn</button><button class="btn dark" data-act="storage-advanced">Dán JSON mới</button></div>`;
 return `<div class="storage-arsenal storage-vault v38-data-shell">
   <section class="panel v38-data-hero"><div><span class="chip">KHO DỮ LIỆU TOÁN JSON</span><h3>Trung tâm dữ liệu Toán Bauman</h3><p>Quản lý nguồn JSON theo slot. Import an toàn, Replace/Merge/Restore rõ ràng, tránh dữ liệu cũ đè dữ liệu mới.</p></div>${storageQuickStats()}</section>
   <div class="v38-data-grid">${storageAmmunitionShelf()}<main class="panel v38-data-main"><div class="v38-data-actionrow">${tools}</div><header class="v38-data-main-head"><div><span class="chip ${status[1]==='danger'?'warn-chip':''}">${esc(status[0])}</span><h3>${sourceIcon(name)} ${esc(sourceLabel(name))}</h3><p>${esc(name)}.json · ${esc(sourceKind(name,data))} · ${loaded}/${count}${planned?` · kế hoạch ${planned}`:''}</p></div></header><div class="v38-data-mission">${storageFileMission(name,data).replace('class="arsenal-file-mission"','class="arsenal-file-mission v38-data-mission-inner"')}</div><div class="v38-data-preview clean-scroll">${storagePreview(name,data)}</div></main></div>
 </div>`;
}





