/* ===== E34 · QA answer repair + chapter prev/next + object-safe dialogue ===== */












function v39NormalizePickerMode(mode){return String(mode||'theory').replace(/^writing-(theory|application)$/,'writing');}




function v39NavigateChapter(mode,dir){
 const pack=v37RecordsForMode(mode); const records=arr(pack.records); if(!records.length){toast('Chưa có nội dung để chuyển chương');return;}
 const active=pack.active||records[0]; const chapters=[]; const seen=new Set();
 records.forEach(x=>{const k=str(x.chapterId||x.lessonId||x.id||''); if(k&&!seen.has(k)){seen.add(k); chapters.push({key:k,item:x});}});
 if(!chapters.length){toast('Không xác định được chương');return;}
 const currentKey=str(active.chapterId||active.lessonId||active.id||chapters[0].key);
 let i=chapters.findIndex(c=>c.key===currentKey); if(i<0)i=0;
 const ni=Math.max(0,Math.min(chapters.length-1,i+dir)); if(ni===i){toast(dir>0?'Đang ở chương cuối':'Đang ở chương đầu');return;}
 v39SelectRecordForMode(mode,chapters[ni].item); if(state.modalType==='resource-picker')closeModal(); save(); render(); toast((dir>0?'Đã sang chương sau: ':'Đã về chương trước: ')+(chapters[ni].item.chapterTitle||chapters[ni].item.title||chapters[ni].key));
}








/* ===== END E34 ===== */



/* ===== E35 · Deep polish: compact premium view + safer oral QA ===== */
function e35ModeMeta(mode){
 const base=v37ModeMeta(v39NormalizePickerMode(mode));
 if(mode==='writing')return {label:'Mô phỏng tổng hợp',icon:'🔬',chip:'LAB',title:'Mô phỏng tổng hợp',hint:'Chọn chương, đổi biến và kiểm công thức.'};
 if(mode==='writing')return {label:'Mô phỏng tổng hợp',icon:'🧪',chip:'CASE',title:'Mô phỏng tổng hợp',hint:'Chọn case AI/kỹ thuật, đọc input-output và giới hạn.'};
 return base;
}
function v39TextFromAny(x){
 if(x==null)return '';
 if(typeof x==='string'||typeof x==='number'||typeof x==='boolean')return String(x);
 if(Array.isArray(x))return x.map(v39TextFromAny).filter(Boolean).join(' · ');
 if(typeof x==='object'){
  const keys=['question','answer','answer_vi','modelAnswer','shortAnswer','vi','ru','text','text_vi','text_ru','prompt','body','content','summary','meaning','meaning_vi','title','label','name'];
  for(const k of keys){if(x[k]!=null&&x[k]!==''&&typeof x[k]!=='object')return String(x[k]);}
  const parts=[]; Object.keys(x).forEach(k=>{if(!['id','stage','lessonId','chapterId','slides','blocks','type','kind'].includes(k)){const v=v39TextFromAny(x[k]); if(v)parts.push(v);}});
  return parts.join(' · ');
 }
 return String(x||'');
}
function v39ChapterNavButtons(mode){return `<div class="v39-chapter-nav e35-nav-duo"><button class="btn" data-act="chapter-prev" data-picker-mode="${esc(mode)}">← Chương trước</button><button class="btn" data-act="chapter-next" data-picker-mode="${esc(mode)}">Chương sau →</button></div>`;}






function dialogueTurns(d){
 const raw=arr(A.dialogueTurns?.(d)||d?.utterances||d?.turns); if(raw.length)return raw;
 const qs=arr(d?.professorQuestionsDetailed||d?.qaPairs||d?.questions); if(qs.length)return qs.flatMap(q=>[{speaker:'GV',role:'professor',text:v39TextFromAny(q.question||q.q||q),answer_vi:v39TextFromAny(q.answer||q.a||d?.modelAnswer||'')},{speaker:'HV',role:'student',text:v39TextFromAny(q.answer||q.a||d?.modelAnswer||''),model:true}]);
 return [];
}
function dialogueText(t){return v39TextFromAny(t?.question||t?.ru||t?.text_ru||t?.text||t?.vi||t);}
function dialogueVi(t){const a=v39TextFromAny(t?.answer_vi||t?.answer||t?.modelAnswer||''); return a&&a!==dialogueText(t)?a:'';}
function v39LineAnswer(active,line){return v39TextFromAny(line?.answer_vi||line?.answer||line?.modelAnswer||active?.modelAnswer||active?.shortAnswer||'');}
function v39QaPairs(active){const d=arr(active?.professorQuestionsDetailed||active?.qaPairs); if(d.length)return d.map(x=>({question:v39TextFromAny(x.question||x.q||x),answer:v39TextFromAny(x.answer||x.a||active?.modelAnswer||'')})); return arr(active?.professorQuestions).map(q=>({question:v39TextFromAny(q),answer:v39TextFromAny(active?.modelAnswer||active?.shortAnswer||'')}));}
function renderDialogue(){
 const pack=v37RecordsForMode('dialogue'); let list=pack.records; if(!list.length)list=byStage(getBasicSpeakingDialogues()); const active=list.find(x=>(x.id||x.title)===state.dialogueId)||pack.active||list[0]||{};
 const turns=dialogueTurns(active); const idx=Math.min(state.dialogueLineIndex,Math.max(0,turns.length-1)); const line=turns[idx]||turns[0]||{};
 const title=A.dialogueTitle?.(active)||active?.title||'Vấn đáp giáo sư'; const purpose=A.dialogueSubtitle?.(active)||active?.purpose||'Câu hỏi lý thuyết thực tế giáo sư có thể hỏi trong lớp, seminar hoặc bảo vệ.'; const prog=dialogueProgress(active); const ans=v39LineAnswer(active,line);
 const answerPlan=arr(active.expectedAnswerStructure).slice(0,5); const qaPairs=v39QaPairs(active).slice(0,6);
 const roleLine=(t,i)=>`<button class="v39-oral-step e35-oral-step ${i===idx?'active':''}" data-line="${i}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(dialogueText(t)||'Câu hỏi/trả lời')}</b><small>${esc(dialogueSpeaker(t,i)||'')}</small></button>`;
 return `<div class="v39-oral-shell e34-oral-shell e35-oral-shell">${v39CompactPickerBar('dialogue',title,list.length,v39DialogueFilters())}<section class="panel v39-oral-main e34-oral-main e35-oral-main"><header class="v39-oral-title e35-oral-title"><div><span class="chip">🎙️ ${esc(active.lessonId||active.id||'ORAL')}</span><h3>${esc(title)}</h3><p>${esc(purpose)}</p></div><div class="v39-oral-score e35-oral-score"><b>${prog.percent}%</b><span>${prog.ok}/${prog.total}</span></div></header><article class="v39-oral-question e35-oral-question"><span>Lượt ${turns.length?idx+1:0}/${turns.length||0}</span><h2>${esc(dialogueText(line)||'Chọn câu hỏi bằng nút Chọn chương.')}</h2></article>${ans?`<article class="e34-model-answer e35-model-answer"><span>ĐÁP ÁN MẪU / TỰ KIỂM ĐÚNG SAI</span><p>${esc(ans)}</p></article>`:''}<div class="v39-oral-actions e35-oral-actions"><button class="btn" data-act="prev-line">← Trước</button><button class="btn green" data-act="speak-line">🔊 Nghe</button><button class="btn" data-act="record-line">🎙️ Tập trả lời</button><button class="btn primary" data-act="next-line">Tiếp →</button><button class="btn green" data-act="mark-line-ok">✓ Ổn</button></div><section class="v39-oral-grid e35-oral-grid"><article><h4>Khung trả lời chuẩn</h4><ol>${answerPlan.length?answerPlan.map(x=>`<li>${esc(v39TextFromAny(x))}</li>`).join(''):'<li>Bản chất</li><li>Công thức và điều kiện</li><li>Ứng dụng</li>'}</ol></article><article><h4>Thuật ngữ Việt - Nga - Anh</h4>${mathTermsTable(active.terminologyTerms)}</article></section><details class="v39-oral-map e35-oral-map" open><summary>Bản đồ lượt hỏi <span>${turns.length?idx+1:0}/${turns.length||0}</span></summary><div>${turns.length?turns.map(roleLine).join(''):'<div class="note">Chưa có lượt hỏi/đáp.</div>'}</div></details>${qaPairs.length?`<details class="v39-oral-prof e34-qa-pairs e35-qa-pairs" open><summary>Câu giáo sư hay hỏi + đáp án mẫu</summary><div>${qaPairs.map((q,i)=>`<article><b>Câu ${i+1}: ${esc(q.question)}</b><p>${esc(q.answer||active.modelAnswer||'Cần bổ sung đáp án mẫu.')}</p></article>`).join('')}</div></details>`:''}</section></div>`;
}
