/* ===== E36 · Theory→Exercise CTA + Exercise Minimal View + Simulation/Formula Nav Polish ===== */
function learningUnlockedLevels(day=rawLearningDay()){return ['easy','medium','hard','expert'];}
function isLearningLevelUnlocked(level){return true;}
function exerciseLevelOptions(selected=state.exerciseLevel){
 const levels=['all','easy','medium','hard','expert'];
 return levels.map(l=>`<option value="${l}" ${selected===l?'selected':''}>${esc(l==='all'?'Tất cả mức độ':examLevelLabel(l))}</option>`).join('');
}


function e36ChapterKeyOf(item){return str(item?.chapterId||item?.sourceChapterId||item?.moduleId||item?.lessonId||item?.id||'');}
function e36LessonChapterKey(l){return str(l?.chapterId||l?.sourceChapterId||l?.moduleId||l?.id||l?.lessonId||'');}
function e36FirstLessonOfNextChapter(currentLessonIdOrItem,dir=1){
 const lessons=getLessons(); if(!lessons.length)return '';
 const current=typeof currentLessonIdOrItem==='string'?lessons.find(l=>lessonKey(l)===currentLessonIdOrItem):currentLessonIdOrItem;
 const curKey=e36LessonChapterKey(current||activeLessonContext().lesson||lessons[0]);
 const chapters=[]; const seen=new Set();
 lessons.forEach(l=>{const k=e36LessonChapterKey(l); if(k&&!seen.has(k)){seen.add(k); chapters.push({key:k,lesson:l});}});
 let i=chapters.findIndex(c=>c.key===curKey); if(i<0)i=0;
 const ni=Math.max(0,Math.min(chapters.length-1,i+dir));
 return lessonKey(chapters[ni]?.lesson||lessons[0]);
}
function e36GoTheoryToLesson(id){
 state.view='learning'; state.learnTab='theory'; if(id)state.lessonId=id; state.slide=0; state.exerciseIndex=0; state.practiceDialogueId=''; state.practiceLineIndex=0; save(); render();
}
function e36MoveFormulaChapter(kind,dir){
 const list=kind==='grammar'?grammarDeepItems():getVocab(); if(!list.length){toast('Chưa có công thức để chuyển chương');return;}
 const index=kind==='grammar'?state.grammarIndex:state.vocabIndex; const active=list[Math.max(0,Math.min(index,list.length-1))]||list[0];
 const chapters=[]; const seen=new Set();
 list.forEach((x,i)=>{const k=str(x.chapterId||x.lessonId||x.id||''); if(k&&!seen.has(k)){seen.add(k); chapters.push({key:k,index:i,item:x});}});
 const curKey=str(active.chapterId||active.lessonId||active.id||chapters[0]?.key||''); let ci=chapters.findIndex(c=>c.key===curKey); if(ci<0)ci=0;
 const ni=Math.max(0,Math.min(chapters.length-1,ci+dir)); if(ni===ci){toast(dir>0?'Đang ở chương công thức cuối':'Đang ở chương công thức đầu');return;}
 if(kind==='grammar')state.grammarIndex=chapters[ni].index; else {state.vocabIndex=chapters[ni].index; state.vocabFlipped=false; state.vocabPage=Math.floor((state.vocabIndex||0)/(VOCAB_PAGE_SIZE||20));}
 save(); render(); toast((dir>0?'Sang chương công thức sau: ':'Về chương công thức trước: ')+(v35FormulaChapterLabel(chapters[ni].item)||chapters[ni].key));
}
document.addEventListener('click',function(e){
 const b=e.target.closest('button,[data-act]'); if(!b)return;
 const act=b.dataset.act||'';
 if(act==='exercise-next-chapter-theory'){e.preventDefault(); e.stopPropagation(); const ctx=activeLessonContext(); const active=getExercises()[state.exerciseIndex]||{}; const id=e36FirstLessonOfNextChapter(active.lessonId||ctx.lesson||ctx.id,1); e36GoTheoryToLesson(id); toast('Đã mở lý thuyết chương tiếp theo'); return;}
 if(act==='formula-prev'||act==='formula-next'){e.preventDefault(); e.stopPropagation(); e36MoveFormulaChapter('vocab',act==='formula-next'?1:-1); return;}
 if(act==='grammar-prev'||act==='grammar-next'){e.preventDefault(); e.stopPropagation(); e36MoveFormulaChapter('grammar',act==='grammar-next'?1:-1); return;}
},true);
function v39CompactPickerBar(mode,currentTitle,count,extra=''){
 const m=e35ModeMeta?e35ModeMeta(mode):v37ModeMeta(v39NormalizePickerMode(mode));
 if(mode==='exercises')return '';
 return `<section class="panel v39-picker-bar e34-picker-bar e35-picker-bar e36-picker-bar" data-picker-mode="${esc(mode)}">
  <div class="v39-picker-copy e35-picker-copy"><span class="chip">${esc(m.icon+' '+m.chip)}</span><h3>${esc(currentTitle||m.title)}</h3><p>${esc(m.hint)}</p></div>
  <div class="v39-picker-tools e35-picker-tools e36-picker-tools">${extra?`<div class="v39-filter-min e35-filter-min">${extra}</div>`:''}${v39ChapterNavButtons(mode)}<button class="btn primary v39-pick-btn e35-pick-btn" data-act="open-resource-picker" data-picker-mode="${esc(mode)}"><span>☷</span><b>Chọn chương</b></button><span class="v39-count e35-count">${esc(String(count||0))} mục</span></div>
 </section>`;
}
function renderLearning(){
 const lessons=getLessons(), concepts=getConcepts(); let body='';
 try{if(state.learnTab==='theory')body=renderTheory(lessons,concepts,activeLessonContext().lesson); if(state.learnTab==='exercises')body=renderExercises(); if(state.learnTab==='practice')body=renderPractice(); if(state.learnTab==='review')body=renderReview(); if(state.learnTab==='exam')body=renderExam();}
 catch(e){console.error('Learning tab render error E36',state.learnTab,e);body=`<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI TAB HỌC TẬP</span><h3>Không render được mục ${esc(state.learnTab||'học tập')}</h3><p>${esc(e?.message||e)}</p><button class="btn primary" data-learn="theory">Quay lại Lý thuyết</button></section>`;}
 const activeLearnTab=LEARN_TABS.find(t=>t[0]===state.learnTab)||LEARN_TABS[0];
 const structureMenu=`<details class="learn-structure-menu v39-learn-menu e35-learn-menu e36-learn-menu"><summary class="learn-structure-trigger"><span>🧭</span><b>Cấu trúc bài học</b><u>▾</u></summary><div class="learn-structure-dropdown" role="menu">${LEARN_TABS.map(t=>`<button class="learn-structure-choice ${state.learnTab===t[0]?'active':''}" data-learn="${t[0]}"><span>${t[1]}</span><b>${esc(t[2])}</b></button>`).join('')}</div></details>`;
 const picked=['theory','practice'].includes(state.learnTab); const pack=picked?v37RecordsForMode(state.learnTab):{records:[],active:{}};
 const title=state.learnTab==='theory'?(A.lessonTitle?.(activeLessonContext().lesson)||activeLessonContext().lesson?.title||'Chọn bài giảng'): state.learnTab==='practice'?(A.dialogueTitle?.(pack.active)||pack.active?.title||'Chọn ứng dụng'):activeLearnTab[2];
 const picker=picked?v39CompactPickerBar(state.learnTab,title,(pack.records||[]).length,v39LearningFilters(state.learnTab)):'';
 return `<div class="learn-canva-shell v39-learning-shell e35-learning-shell e36-learning-shell e36-mode-${esc(state.learnTab||'mode')}"><section class="panel v39-learn-top e35-learn-top e36-learn-top"><div class="v39-learn-left">${structureMenu}<div class="learn-structure-indicator e35-mode-indicator"><span>${activeLearnTab[1]}</span><div><b>${esc(activeLearnTab[2])}</b><small>${state.learnTab==='exercises'?'Tập trung làm bài, không bảng chọn chương dư thừa.':(picked?'Chọn chương gọn, nội dung ưu tiên hiển thị.':'Mục kiểm tra/ôn tập độc lập.')}</small></div></div></div><div class="v39-lesson-chip e35-lesson-chip"><span class="chip">${esc(activeLessonContext().id||'Bài học')}</span></div></section>${picker}<main class="v39-tab-content e35-tab-content e36-tab-content">${body}</main></div>`;
}
function renderTheory(lessons,concepts,currentLessonArg){
 const lesson=currentLessonArg||currentLesson(); const {slides,idx}=clampSlideIndex(lesson); const slide=slides[idx]||{};
 const atEnd=idx>=Math.max(0,slides.length-1);
 const theorySimBtn=A.subjectKind==='mathematics'?`<button class="btn gold math-sim-open-btn theory-open" data-open-simulation="theory" data-sim-target="${esc(lessonKey(lesson))}"><span>↗</span><b>Mô phỏng</b></button>`:'';
 const pct=slides.length?Math.round(((idx+1)/slides.length)*100):0;
 const exerciseCta=atEnd?`<footer class="e36-theory-next"><div><span class="chip">Đã hết nội dung lý thuyết</span><b>Chuyển sang luyện bài ngay trong chương này</b><p>Đọc xong công thức, bước tiếp theo là làm bài để kiểm tra hiểu thật.</p></div><button class="btn primary" data-learn="exercises">Bài tập →</button></footer>`:'';
 return `<section class="panel lesson-reader v1257-theory-main v1261-theory-main v1271-theory-main v1295-theory-tight e35-theory-reader e36-theory-reader">
   <div class="lesson-reader-top v1257-reader-top v1271-theory-head v1283-theory-head v1295-theory-head e35-theory-head e36-theory-head">
     <div class="e35-theory-title"><span class="chip">${esc(lesson?.id||'LESSON')} · ${esc(stageTitle(stageOf(lesson)||state.stage))}</span><b>${esc(slide?.title||A.lessonTitle?.(lesson)||lesson?.title||'Bài học')}</b><small>${esc(lesson?.chapterTitle||lesson?.departmentTitle||'')}</small></div>
     <div class="lesson-tools v1271-theory-tools e35-theory-tools e36-theory-tools">${v39ChapterNavButtons('theory')}<button class="btn" data-act="prev-slide" ${idx<=0?'disabled':''}>←</button><span class="chip">${idx+1}/${slides.length||1}</span><button class="btn" data-act="next-slide" ${atEnd?'disabled':''}>→</button>${theorySimBtn}<button class="btn primary" data-act="open-present">⛶ Trình chiếu</button></div>
   </div>
   <div class="e35-progress e36-progress"><i style="width:${pct}%"></i><span>${pct}%</span></div>
   <div class="slide-strip v1257-slide-strip v1261-slide-strip v1271-slide-strip e35-slide-strip e36-slide-strip" aria-label="Thanh chọn slide">${slides.map((sl,i)=>`<button class="slide-nav compact-slide v1271-slide-pill e35-slide-pill e36-slide-pill ${i===idx?'active':''}" data-slide="${i}" title="${esc(sl.title||lesson?.title||'Slide')}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(sl.title||lesson?.title||'Slide')}</b></button>`).join('')}</div>
   <div class="lesson-content slidebox v1257-lesson-content v1261-lesson-content v1271-lesson-content v1295-theory-scroll e35-lesson-content e36-lesson-content" tabindex="0"><article class="slide v1271-slide-page v1295-slide-page e35-slide-page e36-slide-page">${slideBody(slide,lesson)}</article>${exerciseCta}</div>
 </section>`;
}
function renderExercises(){
 const ctx=activeLessonContext();
 const allForLesson=byStage(call('getExercises',[],DB)).filter(x=>ctx.id&&sameLesson(x,ctx.id));
 let xs=getExercises().slice(0,240);
 if(state.exerciseIndex>=xs.length)state.exerciseIndex=Math.max(0,xs.length-1);
 const active=xs[state.exerciseIndex]||xs[0]||null;
 const level=active?canonicalLevel(A.exerciseLevel?.(active)||active?.level||active?.difficulty||state.exerciseLevel||'easy'):'all';
 const prompt=active?cleanExercisePrompt(active):''; const answer=active?renderExerciseSourceAnswer(active):'';
 const taskTitle=active?clip(str(A.exerciseTitle?.(active)||active.title||'Bài tập'),140):'Bài tập';
 const prevDisabled=!active||state.exerciseIndex<=0; const nextDisabled=!active||state.exerciseIndex>=xs.length-1;
 const progress=xs.length?Math.round(((state.exerciseIndex+1)/xs.length)*100):0;
 const nextLesson=e36FirstLessonOfNextChapter(active?.lessonId||ctx.lesson||ctx.id,1);
 const levels=uniq(allForLesson.map(x=>canonicalLevel(A.exerciseLevel?.(x)||x.level||x.difficulty||'easy'))).filter(Boolean);
 const levelPills=['all',...['easy','medium','hard','expert'].filter(l=>levels.includes(l))].map(l=>`<button class="btn e36-level-pill ${state.exerciseLevel===l?'active':''}" data-exercise-level-set="${l}">${esc(l==='all'?'Tất cả':examLevelLabel(l))}</button>`).join('');
 const body=active?`<article class="exercise-nine-card e36-exercise-card" tabindex="0">
     <header class="exercise-nine-title e36-exercise-title"><div><span class="chip">${esc(level==='all'?'Bài tập':examLevelLabel(level))}</span><h3>${esc(taskTitle)}</h3></div><b>${state.exerciseIndex+1}/${xs.length}</b></header>
     <div class="exercise-nine-progress e36-exercise-progress" aria-label="Tiến độ bài tập"><i style="width:${progress}%"></i><span>${progress}%</span></div>
     <section class="exercise-nine-prompt e36-exercise-prompt"><b>Yêu cầu</b><div>${esc(prompt||'Chưa có yêu cầu bài tập.').replace(/\n/g,'<br>')}</div></section>
     <details class="exercise-nine-answer e36-exercise-answer"><summary>Xem đáp án/rubric sau khi tự làm</summary><div>${esc(answer||'Chưa có đáp án/rubric trong dữ liệu gốc.').replace(/\n/g,'<br>')}</div></details>
   </article>`:`<div class="note exercise-nine-empty e36-exercise-empty"><b>Không có bài tập phù hợp bộ lọc hiện tại.</b><span>Bài ${esc(ctx.id)} có ${allForLesson.length} bài tập. Chọn mức khác hoặc quay lại lý thuyết.</span></div>`;
 return `<section class="panel learn-work-card exercise-nine-shell e36-exercise-shell">
   <header class="exercise-nine-head e36-exercise-head"><div><span class="chip">📝 BÀI TẬP · ${esc(ctx.id)}</span><h3>${active?`Bài ${state.exerciseIndex+1}`:'Chưa có câu phù hợp'}</h3><p>${esc(ctx.title||taskTitle)}</p></div><div class="exercise-nine-tools e36-exercise-tools"><button class="btn" data-learn="theory">Xem lại lý thuyết</button><button class="btn" data-act="prev-exercise" ${prevDisabled?'disabled':''}>← Bài trước</button><button class="btn primary" data-act="next-exercise" ${nextDisabled?'disabled':''}>Bài sau →</button><button class="btn green" data-act="exercise-next-chapter-theory" ${nextLesson?'' :'disabled'}>Chương tiếp →</button></div></header>
   <nav class="e36-exercise-levels" aria-label="Bộ lọc mức độ bài tập">${levelPills}</nav>
   ${body}
 </section>`;
}
document.addEventListener('click',function(e){
 const b=e.target.closest('[data-exercise-level-set]'); if(!b)return;
 e.preventDefault(); e.stopPropagation(); state.exerciseLevel=b.dataset.exerciseLevelSet||'all'; state.exerciseIndex=0; save(); render();
},true);


function e36FormulaNav(kind){return `<div class="e36-formula-nav"><button class="btn" data-act="${kind==='grammar'?'grammar-prev':'formula-prev'}">← Chương trước</button><button class="btn" data-act="${kind==='grammar'?'grammar-next':'formula-next'}">Chương sau →</button></div>`;}





/* ===== START E37 · FLOW + COMPACT REGRESSION POLISH ===== */
const E37_PREV_RENDER_EXERCISES=renderExercises;
const E37_PREV_RENDER_THEORY=renderTheory;
