function e39CompactModeMeta(mode){
 const m=(typeof e35ModeMeta==='function'?e35ModeMeta(mode):v37ModeMeta(v39NormalizePickerMode(mode)))||{};
 return {icon:m.icon||'☷',chip:m.chip||'Chọn mục',title:m.title||'Chọn chương',hint:m.hint||''};
}
function e39PlainTitle(x){return str(x||'').replace(/\s+/g,' ').trim();}
function e39SameText(a,b){return lower(e39PlainTitle(a)).replace(/[·:\-–—]/g,'')===lower(e39PlainTitle(b)).replace(/[·:\-–—]/g,'');}
function e39MaybeSmall(text,limit=96){const s=e39PlainTitle(text); return s.length>limit?s.slice(0,limit-1)+'…':s;}
function e39LearningCount(count){return `<span class="v39-count e35-count e39-count">${esc(String(count||0))} mục</span>`;}
/* Gọn hóa mọi picker có nút chọn chương: chỉ giữ điều hướng, lọc và số mục, không lặp tiêu đề nội dung đang hiển thị bên dưới. */
v39CompactPickerBar=function(mode,currentTitle,count,extra=''){
 if(mode==='exercises')return '';
 const m=e39CompactModeMeta(mode);
 return `<section class="panel v39-picker-bar e34-picker-bar e35-picker-bar e36-picker-bar e39-picker-bar" data-picker-mode="${esc(mode)}">
  <div class="v39-picker-copy e35-picker-copy e39-picker-copy"><span class="chip">${esc(m.icon+' '+m.chip)}</span><small>${esc(mode==='theory'?'Đổi bài học nhanh, không lặp tiêu đề nội dung.':'Điều hướng nhanh, tiêu đề chi tiết nằm trong nội dung chính.')}</small></div>
  <div class="v39-picker-tools e35-picker-tools e36-picker-tools e39-picker-tools">${extra?`<div class="v39-filter-min e35-filter-min e39-filter-min">${extra}</div>`:''}${v39ChapterNavButtons(mode)}<button class="btn primary v39-pick-btn e35-pick-btn e39-pick-btn" data-act="open-resource-picker" data-picker-mode="${esc(mode)}"><span>☷</span><b>Chọn chương</b></button>${e39LearningCount(count)}</div>
 </section>`;
};
function e39ExtractFormula(slide,lesson){
 const blocks=arr(slide?.blocks);
 const b=blocks.find(x=>x&&x.formula)||{};
 return e39PlainTitle(b.formula||slide?.formula||lesson?.formula||'');
}
function e39UsefulQuickCheck(slide,lesson){
 const title=e39PlainTitle(slide?.title||A.lessonTitle?.(lesson)||lesson?.title||'khái niệm này');
 const f=e39ExtractFormula(slide,lesson);
 const items=[
  `Nói lại bản chất của “${title}” bằng 1 câu, không đọc chép định nghĩa.`,
  f?`Viết công thức/ký hiệu chính: ${f}. Sau đó nêu điều kiện áp dụng trước khi thay số.`:'Nêu ký hiệu chính và điều kiện áp dụng trước khi giải bài.',
  'Chỉ ra 1 lỗi dễ mắc và 1 dấu hiệu để tự kiểm kết quả.'
 ];
 return `<section class="slide-section e39-quick-check"><h4>Tự kiểm nhanh</h4><ol>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`;
}
function e39GoodNote(slide,lesson){
 const note=normalizeSlideValue(slide?.remember||slide?.note||slide?.professor_note||lesson?.note||'');
 const title=normalizeSlideValue(slide?.title||lesson?.title||'');
 if(!note||e39SameText(note,title))return '';
 return `<section class="slide-section e39-remember"><h4>Ghi nhớ khi làm bài</h4><p>${esc(note).replace(/\n/g,'<br>')}</p></section>`;
}
/* Thay “Tóm tắt” trùng lặp bằng hộp tự kiểm có tác dụng học thật. */
slideExtraSections=function(slide,lesson){return `${e39UsefulQuickCheck(slide,lesson)}${e39GoodNote(slide,lesson)}`;};
function e39GoExercisesFromPresentation(){
 closeModal(); state.view='learning'; state.learnTab='exercises'; state.exerciseIndex=0; save(); render(); toast('Đã đóng trình chiếu và mở Bài tập cùng bài.');
}
function e39GoSimFromPresentation(kind='theory'){
 const lesson=currentLesson(); closeModal(); state.view='storage'; state.simulationKind='unified'; state.simulationTargetId=lessonKey(lesson); save(); render(); toast('Đã đóng trình chiếu và mở Mô phỏng tương ứng.');
}
document.addEventListener('click',function(e){
 const b=e.target.closest('button,[data-act]'); if(!b)return;
 const act=b.dataset.act||'';
 if(act==='presentation-to-exercises'){e.preventDefault();e.stopPropagation();e39GoExercisesFromPresentation();return;}
 if(act==='presentation-to-sim-theory'){e.preventDefault();e.stopPropagation();e39GoSimFromPresentation('theory');return;}
 if(act==='presentation-to-sim-application'){e.preventDefault();e.stopPropagation();e39GoSimFromPresentation('application');return;}
},true);
