 const terms=arr(active.terminologyTerms||active.terms); const steps=arr(active.applicationSteps||active.aiPipeline||active.turns).slice(0,6); const questions=arr(active.analysisQuestions||active.professorQuestions||active.reflectionQuestions||[]).slice(0,6);
 const formula=active.formulaUsed||active.formula||active.coreFormula||lesson.formula||''; const domain=active.applicationDomain||active.purpose||'Ứng dụng Toán vào AI/Bauman';
