 const title=A.dialogueTitle?.(active)||active?.title||'Vấn đáp giáo sư'; const purpose=A.dialogueSubtitle?.(active)||active?.purpose||'Câu hỏi lý thuyết thực tế trong lớp, seminar hoặc bảo vệ.'; const prog=dialogueProgress(active); const ans=v39LineAnswer(active,line);
