/* ===== E40 · Theory summary at slide end + Application exercise-like flow + Simulation content phase 1 ===== */
function e40Norm(s){return String(s||'').toLowerCase().replace(/<[^>]+>/g,' ').replace(/[\s\-–—:;,.!?()\[\]"'“”‘’]+/g,' ').trim();}
function e40TooSimilar(a,b){const A=e40Norm(a),B=e40Norm(b); if(!A||!B)return false; if(A===B)return true; if(A.length>24&&B.includes(A))return true; if(B.length>24&&A.includes(B))return true; const aa=new Set(A.split(' ').filter(x=>x.length>2)); const bb=new Set(B.split(' ').filter(x=>x.length>2)); if(!aa.size||!bb.size)return false; let hit=0; aa.forEach(x=>{if(bb.has(x))hit++;}); return hit/Math.min(aa.size,bb.size)>0.82;}
function e40SentenceParts(s){return normalizeSlideValue(s||'').split(/(?<=[.!?。])\s+|\n+/).map(x=>x.trim()).filter(Boolean);}
function e40BlockTexts(slide){return arr(slide?.blocks).flatMap(b=>{const out=[]; if(b?.body)out.push(b.body); if(b?.text)out.push(b.text); if(b?.content)out.push(b.content); if(b?.formula)out.push('Công thức: '+b.formula); arr(b?.items).forEach(x=>out.push(v39TextFromAny(x))); if(b?.note)out.push(b.note); return out;}).filter(Boolean);}
function e40SmartSummary(slide,lesson){
 const title=normalizeSlideValue(slide?.title||lesson?.title||'');
 const bodyText=e40BlockTexts(slide).join(' ');
 const rawCandidates=[slide?.summary,slide?.takeaway,slide?.remember,lesson?.summary,lesson?.shortSummary].filter(Boolean).flatMap(e40SentenceParts);
 let pool=rawCandidates.concat(e40SentenceParts(bodyText));
 const picked=[];
 for(const cand0 of pool){
  let cand=normalizeSlideValue(cand0).replace(/^Tóm tắt[:：]?\s*/i,'').trim();
  if(!cand||cand.length<22)continue;
  if(e40TooSimilar(cand,title))continue;
  if(picked.some(x=>e40TooSimilar(x,cand)))continue;
  // shorten, but keep meaning
  if(cand.length>190)cand=cand.slice(0,187).replace(/\s+\S*$/,'')+'…';
  picked.push(cand);
  if(picked.length>=3)break;
 }
 if(!picked.length){
  const cleanTitle=title.replace(/\s*·\s*(Bản chất và bài toán|Mở rộng|Ví dụ|Luyện tập).*$/i,'');
  picked.push(`Nắm trọng tâm “${cleanTitle||'bài học'}”: đối tượng toán học, điều kiện áp dụng và cách đọc kết quả.`);
  picked.push('Sau khi đọc, hãy tự viết lại công thức hoặc tiêu chí chính bằng ký hiệu của mình.');
 }
 return `<section class="slide-section e40-slide-summary"><h4>Tóm tắt cuối slide</h4><ul>${picked.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`;
}
slideExtraSections=function(slide,lesson){return `${e39UsefulQuickCheck(slide,lesson)}${e39GoodNote(slide,lesson)}${e40SmartSummary(slide,lesson)}`;};

function e40LessonExercises(lessonId){return getExercises().filter(x=>str(x.lessonId)===str(lessonId));}
function e40AppPoolForLesson(lesson){
 const lessonId=lessonKey(lesson)||lesson?.id||lesson?.lessonId||activeLessonContext().id;
 const chapterId=lesson?.chapterId||'';
 let list=arr(DB.applications).filter(x=>str(x.lessonId)===str(lessonId));
 if(!list.length&&chapterId)list=arr(DB.applications).filter(x=>str(x.chapterId)===str(chapterId));
 if(!list.length)list=getPracticeDialogues().filter(x=>str(x.lessonId)===str(lessonId)||str(x.chapterId)===str(chapterId));
 return list;
}
function e40CurrentAppContext(){
 const ctx=activeLessonContext(); const lesson=currentLesson()||ctx.lesson||{}; const lessonId=lessonKey(lesson)||ctx.id||lesson.id||lesson.lessonId||'';
 const exs=e40LessonExercises(lessonId); const activeEx=exs.find(x=>getExercises().indexOf(x)===state.exerciseIndex)||exs[0]||{};
 const apps=e40AppPoolForLesson(lesson); const idx=Math.min(Math.max(0,Number(state.practiceLineIndex)||0),Math.max(0,apps.length-1));
 return {ctx,lesson,lessonId,exs,activeEx,apps,idx,active:apps[idx]||apps[0]||{}};
}
function e40SetExerciseForLesson(lessonId){const all=getExercises(); const i=all.findIndex(x=>str(x.lessonId)===str(lessonId)); if(i>=0)state.exerciseIndex=i;}
function e40AppFlowFooter(lessonId,active){return `<footer class="e40-app-flow"><div><span class="chip">ỨNG DỤNG · phụ thuộc Lý thuyết</span><b>Đọc lý thuyết trước, ứng dụng sau</b><p>Tab này dùng trực tiếp lý thuyết tương ứng, chuyển công thức sang tình huống kỹ thuật.</p></div><nav><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn primary" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn gold" data-act="app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
function e40RenderApplicationStudy(){
 const C=e40CurrentAppContext(); const active=C.active||{}; const lesson=C.lesson||{}; const activeEx=C.activeEx||{};
 if(!C.apps.length)return `<section class="panel math-app-empty e40-app-empty"><span class="chip">🧩 ỨNG DỤNG</span><h3>Chưa có case ứng dụng cho bài này</h3><p>Hãy quay lại Bài tập hoặc kiểm tra data/applications.json.</p><div class="exercise-nine-tools e36-exercise-tools e40-app-tools"><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn primary" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></div></section>`;
 const terms=arr(active.terminologyTerms||active.terms).slice(0,8);
 const steps=arr(active.applicationSteps||active.aiPipeline||active.turns).slice(0,6);
 const questions=arr(active.analysisQuestions||active.professorQuestions||active.reflectionQuestions||[]).slice(0,5);
 const rubric=arr(active.applicationRubric||active.rubric||[]).slice(0,5);
 const formula=active.formulaUsed||active.formula||active.coreFormula||'';
 const inputs=arr(active.inputs||active.variables||[]).slice(0,4), outputs=arr(active.outputs||active.expectedOutputs||[]).slice(0,4);
 const progress=C.apps.length?Math.round(((C.idx+1)/C.apps.length)*100):0;
 const relatedPrompt=cleanExercisePrompt(activeEx)||active.fromExercise||'Bài tập nguồn: xác định dữ kiện, chọn công thức, tính kết quả và diễn giải.';
 return `<section class="panel learn-work-card exercise-nine-shell e36-exercise-shell e40-app-shell">
  <header class="exercise-nine-head e36-exercise-head e40-app-head"><div><span class="chip">🧩 ỨNG DỤNG · ${esc(C.lessonId||active.lessonId||'LESSON')}</span><h3>Case ${C.idx+1}/${C.apps.length}: ${esc(active.title||'Ứng dụng Toán')}</h3><p>${esc(lesson.title||active.applicationDomain||'Ứng dụng phụ thuộc lý thuyết và bài tập cùng bài.')}</p></div><div class="exercise-nine-tools e36-exercise-tools e40-app-tools"><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn primary" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn" data-act="app-prev" ${C.idx<=0?'disabled':''}>← Case trước</button><button class="btn primary" data-act="app-next" ${C.idx>=C.apps.length-1?'disabled':''}>Case sau →</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></div></header>
  <div class="exercise-nine-progress e36-exercise-progress e40-app-progress"><i style="width:${progress}%"></i><span>${progress}%</span></div>
  <section class="exercise-nine-prompt e36-exercise-prompt e40-app-source"><b>Từ lý thuyết sang ứng dụng</b><div>${esc(relatedPrompt).replace(/\n/g,'<br>')}</div></section>
  <div class="e40-app-grid">
    <article class="panel e40-app-card main"><span>Công thức/tiêu chí dùng</span><h4>${esc(formula||'Dùng công thức trọng tâm của bài tập vừa học')}</h4><p>${esc(active.purpose||active.aiGraduationNeed||'Đọc input, tính output, kiểm điều kiện và diễn giải kết quả kỹ thuật.')}</p></article>
    <article class="panel e40-app-card"><span>Tình huống kỹ thuật</span><p>${esc(active.realLifeScenario||active.realLife||'Biến hiện tượng thật thành dữ liệu đo được, sau đó dùng công thức để ra quyết định.')}</p></article>
  </div>
  <section class="panel e40-app-protocol"><header><span class="chip">QUY TRÌNH</span><h4>Lý thuyết → Case kỹ thuật → Kết luận</h4></header><ol>${steps.length?steps.map(x=>`<li>${esc(v39TextFromAny(x))}</li>`).join(''):'<li>Chọn input.</li><li>Tính output.</li><li>Đọc sai số/giới hạn.</li><li>Kết luận.</li>'}</ol></section>
  <section class="math-app-two-col e40-app-two-col"><article class="panel"><h4>Input → Output</h4><div class="math-io-grid"><div><b>Input</b>${inputs.length?inputs.map(x=>`<span>${esc(x.label||x.name||v39TextFromAny(x))}</span>`).join(''):'<span>Biến, tham số, dữ liệu đo</span>'}</div><div><b>Output</b>${outputs.length?outputs.map(x=>`<span>${esc(x.label||x.name||v39TextFromAny(x))}</span>`).join(''):'<span>Kết quả, sai số, quyết định kỹ thuật</span>'}</div></div></article><article class="panel"><h4>Tiêu chí tự chấm</h4><ul>${rubric.length?rubric.map(x=>`<li>${esc(v39TextFromAny(x))}</li>`).join(''):'<li>Có input/output rõ.</li><li>Có công thức.</li><li>Có kết luận kỹ thuật.</li>'}</ul></article></section>
  ${questions.length?`<section class="panel e40-app-questions"><h4>Câu tự kiểm ứng dụng</h4><ol>${questions.map(q=>`<li>${esc(v39TextFromAny(q))}</li>`).join('')}</ol></section>`:''}
  ${terms.length?`<section class="panel e40-app-terms"><h4>Thuật ngữ cần nói được</h4>${mathTermsTable(terms)}</section>`:''}
  ${e40AppFlowFooter(C.lessonId,active)}
 </section>`;
}
renderPractice=function(){return e40RenderApplicationStudy();};

// Ứng dụng dùng luồng tối giản như Bài tập: không picker/chọn chương ở đầu tab.
const E40_PREV_COMPACT_PICKER=v39CompactPickerBar;
v39CompactPickerBar=function(mode,currentTitle,count,extra=''){
 if(mode==='exercises'||mode==='practice')return '';
 return E40_PREV_COMPACT_PICKER(mode,currentTitle,count,extra);
};

document.addEventListener('click',function(e){
 const b=e.target.closest('button,[data-act]'); if(!b)return; const act=b.dataset.act||'';
 if(act==='app-prev'||act==='app-next'){
  e.preventDefault(); e.stopPropagation(); const C=e40CurrentAppContext(); const d=act==='app-next'?1:-1; state.practiceLineIndex=Math.max(0,Math.min(Math.max(0,C.apps.length-1),C.idx+d)); save(); render(); return;
 }
 if(act==='app-open-exercise-legacy'){
  e.preventDefault(); e.stopPropagation(); const C=e40CurrentAppContext(); state.view='learning'; state.learnTab='exercises'; state.lessonId=C.lessonId; e40SetExerciseForLesson(C.lessonId); save(); render(); toast('Đã mở Bài tập tương ứng.'); return;
 }
 if(act==='app-open-theory'){
  e.preventDefault(); e.stopPropagation(); const C=e40CurrentAppContext(); state.view='learning'; state.learnTab='theory'; state.lessonId=C.lessonId; state.slide=0; save(); render(); toast('Đã mở lại Lý thuyết tương ứng.'); return;
 }
 if(act==='app-open-sim'){
  e.preventDefault(); e.stopPropagation(); const C=e40CurrentAppContext(); state.view='storage'; state.simulationKind='unified'; state.simulationTargetId=C.active.id||C.active.lessonId||C.lessonId; save(); render(); toast('Đã mở Mô phỏng tổng hợp tương ứng.'); return;
 }
},true);

/* ===== END E40 ===== */



/* ===== E41 · Simulation Deep Interactive Lab ===== */
function e41Num(v,d=0){const n=Number(v);return Number.isFinite(n)?n:d;}
function e41ClipList(xs,n=5){return arr(xs).slice(0,n).map(v39TextFromAny).filter(Boolean);}


function e41Slider(v,i){
 const min=e41Num(v.min,0), max=e41Num(v.max,10), def=e41Num(v.default,(min+max)/2), step=e41Num(v.step,(max-min)/100||.1); const pct=max===min?50:Math.round((def-min)*100/(max-min));
 return `<article class="e41-slider" data-e41-var="${i}"><label><span>${esc(v.label||v.name||('Biến '+(i+1)))}</span><output>${esc(def)}</output></label><input data-e41-range="1" type="range" min="${esc(min)}" max="${esc(max)}" step="${esc(step)}" value="${esc(def)}" style="--p:${pct}%"><small>${esc(v.effect||'Đổi biến và đọc output.')}</small></article>`;
}
function e41ScenarioButtons(active){const xs=arr(active.labScenarios); const fallback=['Baseline','Stress test','Compare','Failure case']; const names=xs.length?xs.map(x=>x.name||x.title||'Scenario'):fallback; return names.slice(0,4).map((x,i)=>`<button class="btn ${i===0?'primary':''}" data-act="e41-scenario" data-scenario="${i}">${esc(x)}</button>`).join('');}
function e41MetricCards(){return `<div class="e41-metrics"><article class="e41-metric"><b data-e41-out="score">0.00</b><span>score/output</span></article><article class="e41-metric"><b data-e41-out="stability">ổn</b><span>độ ổn định</span></article><article class="e41-metric"><b data-e41-out="decision">kiểm</b><span>quyết định</span></article></div>`;}
function e41InteractiveBoard(active,kind){
 const model=active.simulationModel||{}; const vars=arr(active.variables).slice(0,5); const read=e41ClipList(active.computedReadouts,3); const scenarios=arr(active.labScenarios).slice(0,4); const checks=e41ClipList(active.interpretationChecklist||active.commonMisreadings,6); const report=e41ClipList(active.reportTemplate,6); const pseudo=e41ClipList(active.pseudoCode||active.explorationSteps,6);
 return `<section class="e41-lab-grid"><article class="e41-board"><div class="e41-board-top"><div><span class="chip">${esc(String(model.profile||kind).toUpperCase())} · ${esc(model.visualMode||'interactive board')}</span><b>${esc(active.title||'Mô phỏng')}</b></div><span class="chip">UNIFIED LAB</span></div><div class="e41-visual" data-e41-visual><div class="e41-bars"><i></i><i></i><i></i><i></i></div><i class="e41-dot"></i></div><div class="e41-equation"><span class="chip">CÔNG THỨC / MODEL</span><pre>${esc(active.formula||model.readoutFormula||'score = f(input, điều kiện, nhiễu)')}</pre><p>${esc(model.interpretation||active.purpose||'Đổi biến và đọc kết quả theo điều kiện áp dụng.')}</p></div></article><aside class="e41-control"><header><div><span class="chip">CONTROL PANEL</span><h3>Đổi biến có kiểm soát</h3></div><button class="btn" data-act="e41-reset">Reset</button></header>${vars.length?vars.map(e41Slider).join(''):'<div class="note">Chưa có biến điều khiển.</div>'}<div class="e41-scenario-row">${e41ScenarioButtons(active)}</div></aside></section><section class="e41-dual"><article class="e41-read"><header><span class="chip">READOUT</span><b>Đọc kết quả</b></header>${e41MetricCards()}${read.length?`<ul>${read.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</article><article class="e41-checklist"><header><span class="chip">CHECKLIST</span><b>Diễn giải</b></header><ul>${(checks.length?checks:['Kết quả có đúng chiều với công thức không?','Điều kiện áp dụng còn thỏa không?','Kết luận có nối lại bài tập không?']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article></section><section class="e41-dual"><article class="e41-report"><header><span class="chip">PSEUDOCODE</span><b>Quy trình chạy lab</b></header><ol>${(pseudo.length?pseudo:['Chọn baseline.','Đổi một biến.','Đọc output.','Viết kết luận.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article><article class="e41-report"><header><span class="chip">BÁO CÁO NGẮN</span><b>Mẫu ghi kết quả</b></header><ul>${(report.length?report:['Baseline: ...','Biến chi phối: ...','Kết luận: ...']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${scenarios.length?`<details><summary>Kịch bản thử nghiệm</summary><ol>${scenarios.map(x=>`<li><b>${esc(x.name||x.title||'Scenario')}:</b> ${esc(x.setup||'Thiết lập')} → ${esc(x.task||'Nhiệm vụ')}</li>`).join('')}</ol></details>`:''}</article></section>`;
}
function e41UpdateLab(root){
 root=root?.closest?root.closest('.e41-sim-workbench'):root; if(!root)return; const ranges=[...root.querySelectorAll('[data-e41-range]')]; if(!ranges.length)return;
 let vals=ranges.map(r=>{const min=e41Num(r.min,0),max=e41Num(r.max,1),v=e41Num(r.value,min); const p=max===min?0:(v-min)/(max-min); const out=r.closest('.e41-slider')?.querySelector('output'); if(out)out.textContent=String(v); return Math.max(0,Math.min(1,p));});
 const avg=vals.reduce((a,b)=>a+b,0)/vals.length; const noise=vals[1]??0.2; const threshold=vals[2]??0.5; const score=Math.max(0,Math.min(1,avg*0.78+(threshold*.18)-(noise*.22)+0.16)); const stable=noise<.38?'ổn':(noise<.72?'nhạy':'rủi ro'); const decision=score>.72?'chấp nhận':(score>.46?'kiểm thêm':'bác bỏ');
 const put=(k,v)=>{const el=root.querySelector(`[data-e41-out="${k}"]`); if(el)el.textContent=v;}; put('score',score.toFixed(2)); put('stability',stable); put('decision',decision);
 const dot=root.querySelector('.e41-dot'); if(dot){dot.style.setProperty('--x',(18+avg*68)+'%'); dot.style.setProperty('--y',(72-score*56)+'%');}
 root.querySelectorAll('.e41-bars i').forEach((b,i)=>b.style.setProperty('--h',Math.max(16,Math.min(94,(score*70)+(i*9)-(noise*17)))+'%'));
}
function e41SetScenario(btn){const root=btn.closest('.e41-sim-workbench'); if(!root)return; const i=Number(btn.dataset.scenario)||0; const presets=[[.45,.18,.55],[.92,.82,.78],[.28,.12,.44],[.75,.96,.88]][i]||[.5,.2,.6]; const ranges=[...root.querySelectorAll('[data-e41-range]')]; ranges.forEach((r,j)=>{const min=e41Num(r.min,0),max=e41Num(r.max,1); const p=presets[Math.min(j,presets.length-1)]; r.value=String(min+(max-min)*p);}); e41UpdateLab(root);}
function renderMathSimulationWorkspace(){
 const S=e41ActiveSimulation(); const {raw,kind,list,active}=S; if(!raw.length)return `<section class="panel learning-recovery-card"><span class="chip">🔬 MÔ PHỎNG</span><h3>Chưa có mô phỏng</h3><p>Hãy thêm dữ liệu vào data/simulations.json.</p></section>`;
 const vars=arr(active.variables).slice(0,5); const file=active.file||''; const src=file?(file.includes('?')?file+'&':file+'?')+'kind='+encodeURIComponent(kind)+'&id='+encodeURIComponent(active.id||''):'simulations/unified_lab.html?kind=unified';
 const flow=`<footer class="e37-flow-footer e37-sim-flow e39-sim-flow e41-flow"><div><span class="chip">SIM → BÁO CÁO</span><b>Chạy lab xong phải viết kết luận</b><p>Đổi biến, đọc output, kiểm điều kiện, rồi quay về bài tập/ứng dụng hoặc sang chương tiếp.</p></div><nav><button class="btn" data-learn="theory">Lý thuyết</button><button class="btn primary" data-learn="exercises">Bài tập</button><button class="btn gold" data-learn="practice">Ứng dụng</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>`;
 return `<div class="mathlab-shell v39-sim-shell e37-mathlab-shell e39-sim-shell e41-sim-shell mode-unified">${v39SimModePanel(raw)}<section class="panel v39-sim-search e39-sim-toolbar e41-sim-toolbar"><div><span class="chip">${esc(mathSimSourceLabel(kind))}</span><small>${esc(active.lessonId||active.id||'SIM')} · ${esc(active.chapterId||stageTitle(active.stage||state.stage))}</small></div><input class="input" data-input="writingQuery" value="${esc(state.writingQuery||'')}" placeholder="Tìm mô phỏng, biến, công thức, case..."></section><main class="panel mathlab-main v39-sim-main e39-sim-main e41-sim-main e41-sim-workbench"><header class="e41-sim-head"><div><span class="chip">${esc(active.lessonId||active.id)} · ${vars.length} biến</span><h3>${esc(active.title||'Mô phỏng')}</h3><p>${esc(active.purpose||active.applicationDomain||active.aiConnection||active.realLifeScenario||'Đổi biến đầu vào và quan sát đầu ra.')}</p></div><nav class="e41-sim-actions"><button class="btn" data-act="e41-reset">Baseline</button><button class="btn primary" data-ai-quick="writing">AI gợi ý kết luận</button></nav></header>${e41InteractiveBoard(active,kind)}<div class="mathlab-frame-wrap e41-sim-frame"><iframe class="mathlab-frame" src="${esc(src)}" loading="lazy"></iframe></div>${flow}</main></div>`;
}
renderWriting=function(){if(A.subjectKind==='mathematics')return renderMathSimulationWorkspace(); return E37_PREV_RENDER_WRITING?E37_PREV_RENDER_WRITING():'';};
document.addEventListener('input',function(e){if(e.target&&e.target.matches('[data-e41-range]'))e41UpdateLab(e.target);},true);
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]'); if(!b)return; const act=b.dataset.act||''; if(act==='e41-scenario'){e.preventDefault();e.stopPropagation();e41SetScenario(b);return;} if(act==='e41-reset'){e.preventDefault();e.stopPropagation();const root=b.closest('.e41-sim-workbench'); if(root){root.querySelectorAll('[data-e41-range]').forEach(r=>{r.value=r.getAttribute('value')||r.value;}); e41UpdateLab(root);} return;}},true);
setTimeout(()=>document.querySelectorAll('.e41-sim-workbench').forEach(e41UpdateLab),80);
/* ===== END E41 ===== */


/* ===== E42 · Final-slide summary + theory-grounded application refocus ===== */
function e42TextParts(v){return normalizeSlideValue(v||'').split(/(?<=[.!?。])\s+|\n+/).map(x=>x.trim()).filter(Boolean);}
function e42Shorten(s,n=150){s=normalizeSlideValue(s||''); if(s.length<=n)return s; return s.slice(0,n-1).replace(/\s+\S*$/,'')+'…';}
function e42SlideTexts(sl){return arr(sl?.blocks).flatMap(b=>{if(typeof b==='string')return [b]; const out=[]; ['body','text','content','summary','note','formula'].forEach(k=>{if(b&&b[k])out.push((k==='formula'?'Công thức: ':'')+v39TextFromAny(b[k]));}); arr(b?.items).forEach(x=>out.push(v39TextFromAny(x))); return out;}).filter(Boolean);}
function e42IsLastSlide(slide,lesson){const slides=slideSetForLesson(lesson); return slides.length&&slides[slides.length-1]===slide;}
function e42WholeLessonSummary(slide,lesson){
 const slides=slideSetForLesson(lesson); const title=e39PlainTitle(A.lessonTitle?.(lesson)||lesson?.title||'bài học');
 const titles=slides.map(s=>e39PlainTitle(s?.title||'')).filter(Boolean).map(t=>t.replace(/\s*·\s*(Bản chất và bài toán|Mở rộng|Ví dụ|Luyện tập|Tổng kết).*$/i,''));
 const uniqTitles=[]; titles.forEach(t=>{if(t&&!uniqTitles.some(x=>e40TooSimilar(x,t)))uniqTitles.push(t);});
 const formulaPool=[]; slides.forEach(sl=>arr(sl?.blocks).forEach(b=>{const f=b?.formula||((b?.type==='formula'||b?.type==='math')?(b?.text||b?.body||b?.content):''); if(f&&!formulaPool.some(x=>e40TooSimilar(String(x),String(f))))formulaPool.push(String(f));}));
 const bodyPool=[]; slides.forEach(sl=>e42SlideTexts(sl).forEach(x=>{x=e42Shorten(x,140); if(x.length>35&&!bodyPool.some(y=>e40TooSimilar(y,x)))bodyPool.push(x);}));
 const flow=uniqTitles.slice(0,5); const formulas=formulaPool.slice(0,4); const ideas=bodyPool.slice(0,4);
 return `<section class="slide-section e42-final-summary"><h4>Tổng kết cuối bài / chương</h4><div class="e42-summary-grid"><article><b>Mạch kiến thức</b><ol>${(flow.length?flow:[title]).map(x=>`<li>${esc(e42Shorten(x,90))}</li>`).join('')}</ol></article><article><b>Công thức/ký hiệu cần nhớ</b><ul>${(formulas.length?formulas:['Viết lại công thức trọng tâm, điều kiện áp dụng và ý nghĩa từng biến.']).map(x=>`<li>${esc(e42Shorten(x,120))}</li>`).join('')}</ul></article><article><b>Biết dùng khi</b><ul>${(ideas.length?ideas:['Xác định dữ liệu đầu vào, chọn công thức đúng, kiểm điều kiện và diễn giải kết quả.']).slice(0,3).map(x=>`<li>${esc(e42Shorten(x,130))}</li>`).join('')}</ul></article></div><p class="e42-summary-note">Tóm tắt này chỉ xuất hiện ở slide cuối để gom toàn bộ mạch học, không lặp ở từng slide.</p></section>`;
}
slideExtraSections=function(slide,lesson){return `${e39UsefulQuickCheck(slide,lesson)}${e39GoodNote(slide,lesson)}${e42IsLastSlide(slide,lesson)?e42WholeLessonSummary(slide,lesson):''}`;};

function e42ApplicationPoolForLesson(lesson){
 const lessonId=lessonKey(lesson)||lesson?.id||lesson?.lessonId||activeLessonContext().id; const chapterId=lesson?.chapterId||'';
 let list=arr(DB.applications).filter(x=>str(x.lessonId)===str(lessonId));
 if(!list.length&&chapterId)list=arr(DB.applications).filter(x=>str(x.chapterId)===str(chapterId));
 if(!list.length)list=getPracticeDialogues().filter(x=>str(x.lessonId)===str(lessonId)||str(x.chapterId)===str(chapterId));
 return list;
}
function e42CurrentAppContext(){
 const ctx=activeLessonContext(); const lesson=currentLesson()||ctx.lesson||{}; const lessonId=lessonKey(lesson)||ctx.id||lesson.id||lesson.lessonId||'';
 const apps=e42ApplicationPoolForLesson(lesson); const idx=Math.min(Math.max(0,Number(state.practiceLineIndex)||0),Math.max(0,apps.length-1));
 return {ctx,lesson,lessonId,apps,idx,active:apps[idx]||apps[0]||{}};
}
function e42AppTheoryAnchor(lesson,active){return active.theoryAnchor||`Từ lý thuyết “${esc(lesson?.shortTitle||lesson?.title||'bài học')}”, xác định biến, công thức, điều kiện và ý nghĩa output trước khi đưa vào tình huống thật.`;}
function e42MiniList(xs,fallback,n=5){xs=arr(xs).map(v39TextFromAny).filter(Boolean).slice(0,n); if(!xs.length)xs=fallback; return xs.map(x=>`<li>${esc(e42Shorten(x,140))}</li>`).join('');}
function e42AppFlowFooter(C){return `<footer class="e40-app-flow e42-app-flow"><div><span class="chip">ỨNG DỤNG · phụ thuộc Lý thuyết</span><b>Lý thuyết → đời sống → lập trình</b><p>Không đi qua tab Bài tập. Mục tiêu là biết công thức dùng vào tình huống nào và khi nào không nên dùng.</p></div><nav><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn gold" data-act="app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
function e42RenderApplicationStudy(){
 const C=e42CurrentAppContext(); const active=C.active||{}; const lesson=C.lesson||{};
 if(!C.apps.length)return `<section class="panel math-app-empty e42-app-empty"><span class="chip">🧩 ỨNG DỤNG</span><h3>Chưa có case ứng dụng cho bài này</h3><p>Ứng dụng cần bám trực tiếp lý thuyết: công thức dùng ở đâu, input/output là gì và điều kiện nào làm kết quả sai.</p><div class="exercise-nine-tools e42-app-tools"><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></div></section>`;
 const formula=active.formulaUsed||active.formula||active.coreFormula||e39ExtractFormula((slideSetForLesson(lesson)||[])[0]||{},lesson)||'Công thức/ký hiệu trọng tâm của bài';
 const progress=C.apps.length?Math.round(((C.idx+1)/C.apps.length)*100):0;
 const real=active.realLifeUse||active.realLifeScenario||active.realLife||'Dùng để chuyển hiện tượng thật thành đại lượng đo được, so sánh được hoặc dự báo được.';
 const code=active.programmingUse||'Trong code: nhận input, kiểm kích thước/đơn vị, tính output theo công thức, trả kết quả kèm cảnh báo điều kiện áp dụng.';
 const when=active.whenToUse||'Dùng khi giả thiết của lý thuyết còn đúng, dữ liệu đủ sạch và output phục vụ một quyết định rõ ràng.';
 const no=active.doNotUseWhen||'Không dùng máy móc khi dữ liệu sai đơn vị, thiếu giả thiết hoặc nhiễu làm kết luận lệch.';
 return `<section class="panel learn-work-card exercise-nine-shell e42-app-shell">
  <header class="exercise-nine-head e42-app-head"><div><span class="chip">🧩 ỨNG DỤNG · ${esc(C.lessonId||active.lessonId||'LESSON')}</span><h3>Case ${C.idx+1}/${C.apps.length}: ${esc(active.title||'Ứng dụng Toán')}</h3><p>${esc(lesson.title||'Ứng dụng trực tiếp từ lý thuyết bài học.')}</p></div><div class="exercise-nine-tools e42-app-tools"><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn" data-act="app-prev" ${C.idx<=0?'disabled':''}>← Case trước</button><button class="btn primary" data-act="app-next" ${C.idx>=C.apps.length-1?'disabled':''}>Case sau →</button><button class="btn gold" data-act="app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></div></header>
  <div class="exercise-nine-progress e42-app-progress"><i style="width:${progress}%"></i><span>${progress}%</span></div>
  <section class="e42-app-core"><article class="e42-theory-anchor"><span>Lý thuyết dùng ở đây</span><h4>${esc(e42Shorten(formula,160))}</h4><p>${esc(e42Shorten(active.theoryAnchor||`Từ lý thuyết “${lesson.shortTitle||lesson.title||'bài học'}”, đặt đúng biến, công thức và điều kiện trước khi áp dụng.`,220))}</p></article><article><span>Trong đời sống/kỹ thuật</span><p>${esc(e42Shorten(real,230))}</p></article><article><span>Trong lập trình</span><p>${esc(e42Shorten(code,230))}</p></article></section>
  <section class="e42-app-when"><article><b>Khi nào dùng?</b><p>${esc(e42Shorten(when,220))}</p></article><article><b>Khi nào không dùng?</b><p>${esc(e42Shorten(no,220))}</p></article><article><b>Output cần nói được</b><p>${esc(e42Shorten(active.compactOutcome||'Kết luận phải nói công thức giúp quyết định điều gì, trong điều kiện nào và sai số ảnh hưởng ra sao.',220))}</p></article></section>
  <section class="panel e42-app-protocol"><header><span class="chip">QUY TRÌNH NGẮN</span><h4>Lý thuyết → ứng dụng thật</h4></header><ol>${e42MiniList(active.applicationSteps,["Đặt biến từ tình huống thật.","Kiểm giả thiết/đơn vị/kích thước.","Tính hoặc mô phỏng output.","Diễn giải thành quyết định kỹ thuật."],5)}</ol></section>
  <section class="panel e42-app-questions"><h4>Câu tự kiểm ứng dụng</h4><ol>${e42MiniList(active.analysisQuestions,["Công thức đang mô hình hóa đại lượng thật nào?","Input trong code là scalar, vector, ma trận hay chuỗi thời gian?","Điều kiện nào làm kết quả không còn đáng tin?"],5)}</ol></section>
  ${e42AppFlowFooter(C)}
 </section>`;
}
renderPractice=function(){return e42RenderApplicationStudy();};

/* Listener phụ cho index ứng dụng E42, không còn đường “Xem lại lý thuyết”. */
document.addEventListener('click',function(e){
 const b=e.target.closest('button,[data-act]'); if(!b)return; const act=b.dataset.act||'';
 if(act==='app-prev'||act==='app-next'){
  e.preventDefault(); e.stopPropagation(); const C=e42CurrentAppContext(); const d=act==='app-next'?1:-1; state.practiceLineIndex=Math.max(0,Math.min(Math.max(0,C.apps.length-1),C.idx+d)); save(); render(); return;
 }
},true);
