/* ===== E43 · hard fix: final-slide-only summary + theory-only application tab ===== */
function e43IsLastSlide(slide,lesson){const slides=slideSetForLesson(lesson); return !!(slides.length && slides[slides.length-1]===slide);}
function e43CleanTitleText(s){return e39PlainTitle(s||'').replace(/\s*·\s*(Bản chất và bài toán|Mở rộng|Ví dụ|Luyện tập|Tổng kết|Tóm tắt mục|Tổng kết toàn bài).*$/i,'').trim();}
function e43FinalSummary(slide,lesson){
 const slides=slideSetForLesson(lesson); const lessonTitle=e43CleanTitleText(A.lessonTitle?.(lesson)||lesson?.shortTitle||lesson?.title||'bài học');
 const flow=[]; slides.forEach(sl=>{const t=e43CleanTitleText(sl?.title||''); if(t&&!flow.some(x=>e40TooSimilar(x,t)))flow.push(t);});
 const formulas=[]; slides.forEach(sl=>arr(sl?.blocks).forEach(b=>{const f=b?.formula||((b?.type==='formula'||b?.type==='math')?(b?.text||b?.body||b?.content):''); if(f&&!formulas.some(x=>e40TooSimilar(String(x),String(f))))formulas.push(String(f));}));
 const appHint=(lesson?.chapterTitle||lesson?.departmentTitle||'AI/kỹ thuật/Bauman');
 return `<section class="slide-section e43-final-summary"><h4>Tổng kết toàn bài</h4><div class="e43-summary-grid"><article><b>Mạch kiến thức</b><ol>${(flow.length?flow:[lessonTitle]).slice(0,5).map(x=>`<li>${esc(e42Shorten(x,96))}</li>`).join('')}</ol></article><article><b>Công thức/ký hiệu</b><ul>${(formulas.length?formulas:['Đối tượng → công thức → điều kiện → output → giới hạn']).slice(0,4).map(x=>`<li>${esc(e42Shorten(x,130))}</li>`).join('')}</ul></article><article><b>Dùng để làm gì?</b><ul><li>Nhận ra dạng bài và chọn đúng công thức.</li><li>Đưa dữ liệu vào code/mô phỏng có kiểm điều kiện.</li><li>Diễn giải output trong ${esc(e42Shorten(appHint,80))}.</li></ul></article></div><p class="e43-summary-note">Khối này chỉ nằm ở slide cuối. Các slide trước không hiển thị tóm tắt để tránh nhiễu và phình giao diện.</p></section>`;
}
/* Không còn tóm tắt cuối từng slide. Slide trước chỉ giữ tự kiểm/ghi nhớ; slide cuối mới có tổng kết toàn bài. */
slideExtraSections=function(slide,lesson){return `${e39UsefulQuickCheck(slide,lesson)}${e39GoodNote(slide,lesson)}${e43IsLastSlide(slide,lesson)?e43FinalSummary(slide,lesson):''}`;};

function e43AppContext(){
 const ctx=activeLessonContext(); const lesson=currentLesson()||ctx.lesson||{}; const lessonId=lessonKey(lesson)||ctx.id||lesson.id||lesson.lessonId||''; const chapterId=lesson.chapterId||'';
 let apps=arr(DB.applications).filter(x=>str(x.lessonId)===str(lessonId)); if(!apps.length&&chapterId)apps=arr(DB.applications).filter(x=>str(x.chapterId)===str(chapterId));
 const idx=Math.min(Math.max(0,Number(state.practiceLineIndex)||0),Math.max(0,apps.length-1)); return {ctx,lesson,lessonId,apps,idx,active:apps[idx]||apps[0]||{}};
}
function e43Lines(xs,fallback,n=4){xs=arr(xs).map(v39TextFromAny).filter(Boolean).slice(0,n); if(!xs.length)xs=fallback; return xs.map(x=>`<li>${esc(e42Shorten(x,150))}</li>`).join('');}
function e43AppEmpty(){return `<section class="panel e43-app-empty"><span class="chip">🧩 ỨNG DỤNG</span><h3>Chưa có ứng dụng cho bài này</h3><p>Ứng dụng phải bám trực tiếp lý thuyết: công thức dùng ở đâu, trong đời sống/kỹ thuật ra sao, trong code viết thế nào.</p><nav><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></section>`;}
function e43RenderApplicationStudy(){
 const C=e43AppContext(); const active=C.active||{}; const lesson=C.lesson||{}; if(!C.apps.length)return e43AppEmpty();
 const formula=active.formulaUsed||active.formula||active.coreFormula||'Công thức/ký hiệu trọng tâm của bài'; const progress=C.apps.length?Math.round(((C.idx+1)/C.apps.length)*100):0;
 const real=active.realLifeUse||active.realLifeScenario||'Dùng lý thuyết để biến tình huống thật thành biến số, phép tính và kết luận kiểm chứng được.';
 const code=active.programmingUse||'Trong lập trình: chuẩn hóa input, kiểm điều kiện, tính output, trả kết quả kèm cảnh báo sai số.';
 const when=active.whenToUse||'Dùng khi giả thiết lý thuyết đúng và dữ liệu đủ sạch.'; const no=active.doNotUseWhen||'Không dùng khi dữ liệu sai đơn vị, thiếu giả thiết hoặc kết luận không kiểm chứng được.';
 const outcome=active.compactOutcome||active.outputModel||'Nói được công thức giúp quyết định điều gì, trong điều kiện nào và giới hạn ra sao.';
 return `<section class="panel learn-work-card e43-app-shell">
  <header class="e43-app-head"><div><span class="chip">🧩 ỨNG DỤNG · phụ thuộc Lý thuyết</span><h3>${esc(active.title||'Ứng dụng thực tế')}</h3><p>${esc(e42Shorten(lesson.title||'Ứng dụng trực tiếp từ nội dung lý thuyết.',150))}</p></div><nav><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn" data-act="app-prev" ${C.idx<=0?'disabled':''}>← Case trước</button><button class="btn primary" data-act="app-next" ${C.idx>=C.apps.length-1?'disabled':''}>Case sau →</button><button class="btn gold" data-act="app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></header>
  <div class="e43-app-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.apps.length}</span></div>
  <section class="e43-app-essence"><article><span>Lý thuyết sử dụng</span><h4>${esc(e42Shorten(formula,160))}</h4><p>${esc(e42Shorten(active.theoryAnchor||'Xác định biến, công thức, điều kiện áp dụng và ý nghĩa output trước khi đưa vào tình huống thật.',230))}</p></article></section>
  <section class="e43-app-grid"><article><span>Trong đời sống/kỹ thuật</span><p>${esc(e42Shorten(real,260))}</p></article><article><span>Trong lập trình</span><p>${esc(e42Shorten(code,260))}</p></article></section>
  <section class="e43-app-when"><article><b>Khi nào dùng</b><p>${esc(e42Shorten(when,220))}</p></article><article><b>Khi nào không dùng</b><p>${esc(e42Shorten(no,220))}</p></article><article><b>Output cần nói được</b><p>${esc(e42Shorten(outcome,220))}</p></article></section>
  <section class="e43-app-two"><article><h4>Quy trình ngắn</h4><ol>${e43Lines(active.applicationSteps,['Đặt biến từ tình huống thật.','Kiểm điều kiện áp dụng.','Tính hoặc mô phỏng output.','Diễn giải thành quyết định.'],4)}</ol></article><article><h4>Câu tự kiểm ứng dụng</h4><ol>${e43Lines(active.analysisQuestions,['Công thức đang mô hình hóa đại lượng thật nào?','Input trong code là gì?','Điều kiện nào làm kết quả không đáng tin?'],3)}</ol></article></section>
  <footer class="e43-app-footer"><div><span class="chip">LÝ THUYẾT → ỨNG DỤNG</span><b>Không phụ thuộc tab Bài tập</b><p>Tab này trả lời: công thức dùng ở đâu, khi nào nên dùng, khi nào tránh dùng, và code cần kiểm gì.</p></div><nav><button class="btn" data-act="app-open-theory">Xem lại lý thuyết</button><button class="btn gold" data-act="app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>
 </section>`;
}
renderPractice=function(){return e43RenderApplicationStudy();};
/* Chặn an toàn mọi nút/nhãn cũ app-open-exercise nếu còn sót trong DOM cache. */
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]'); if(!b)return; if((b.dataset.act||'')==='app-open-exercise'){e.preventDefault();e.stopPropagation();toast('Ứng dụng đã phụ thuộc trực tiếp Lý thuyết, không đi qua Bài tập.'); return;}},true);
