/* ===== E44 · application real-use compact pass + final summary render lock ===== */
function e44Plain(s){return str(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e44Short(s,n=220){s=e44Plain(s); return s.length<=n?s:s.slice(0,n).replace(/\s+\S*$/,'')+'…';}
function e44CurrentLessonFormula(lesson){
 const lid=lessonKey(lesson)||lesson?.id||lesson?.lessonId||'';
 const f=arr(DB.formulas).find(x=>str(x.lessonId)===str(lid));
 if(f)return f.formula||f.term||f.title||'';
 for(const sl of arr(lesson?.slides)){for(const b of arr(sl?.blocks)){if(b?.formula)return b.formula;}}
 return 'đối tượng → công thức → điều kiện áp dụng → output';
}
function e44FinalSummary(slide,lesson){
 const pack=slide?.finalSummaryOnly||{};
 const slides=slideSetForLesson(lesson);
 const flow=arr(pack.knowledgeFlow).length?arr(pack.knowledgeFlow):slides.map(sl=>e43CleanTitleText(sl?.title||'')).filter(Boolean).slice(0,5);
 const formulas=arr(pack.formulas).length?arr(pack.formulas):[e44CurrentLessonFormula(lesson)];
 const uses=arr(pack.useCases).length?arr(pack.useCases):['Nhận dạng dạng bài và chọn công thức đúng.','Chuyển dữ liệu thật thành input trong code/mô phỏng.','Diễn giải output thành kết luận kỹ thuật có điều kiện.'];
 return `<section class="slide-section e44-final-summary"><h4>Tổng kết toàn bài / chương</h4><div class="e44-summary-grid"><article><b>Mạch kiến thức</b><ol>${flow.slice(0,5).map(x=>`<li>${esc(e44Short(x,110))}</li>`).join('')}</ol></article><article><b>Công thức/ký hiệu</b><ul>${formulas.slice(0,4).map(x=>`<li>${esc(e44Short(x,140))}</li>`).join('')}</ul></article><article><b>Dùng để làm gì?</b><ul>${uses.slice(0,4).map(x=>`<li>${esc(e44Short(x,150))}</li>`).join('')}</ul></article></div><p class="e44-summary-note">Tóm tắt chỉ xuất hiện ở slide cuối để chốt mạch học, không lặp ở các slide trước.</p></section>`;
}
slideExtraSections=function(slide,lesson){return `${e39UsefulQuickCheck(slide,lesson)}${e39GoodNote(slide,lesson)}${e43IsLastSlide(slide,lesson)?e44FinalSummary(slide,lesson):''}`;};

function e44AppContext(){
 const ctx=activeLessonContext(); const lesson=currentLesson()||ctx.lesson||{}; const lid=lessonKey(lesson)||ctx.id||lesson.id||lesson.lessonId||''; const ch=lesson.chapterId||'';
 let apps=arr(DB.applications).filter(x=>str(x.lessonId)===str(lid)); if(!apps.length&&ch)apps=arr(DB.applications).filter(x=>str(x.chapterId)===str(ch));
 const idx=Math.min(Math.max(0,Number(state.practiceLineIndex)||0),Math.max(0,apps.length-1));
 return {ctx,lesson,lessonId:lid,chapterId:ch,apps,idx,active:apps[idx]||apps[0]||null};
}
function e44FallbackApp(C){
 const title=e44Short(C.lesson?.shortTitle||C.lesson?.title||'bài học',120); const formula=e44CurrentLessonFormula(C.lesson);
 return {id:'E44-FALLBACK-'+(C.lessonId||'LESSON'),lessonId:C.lessonId,title:'Ứng dụng thật · '+title,dependsOn:'theory',theoryAnchor:`Từ lý thuyết: ${title}. Công thức/ký hiệu: ${formula}.`,realLifeUse:'Dùng lý thuyết để biến hiện tượng thật thành biến số, phép tính và kết luận có thể kiểm chứng.',programmingUse:'Trong code: định nghĩa input, kiểm điều kiện, tính output, log sai số và trả kết luận thay vì chỉ in số.',whenToUse:'Dùng khi giả thiết đúng, dữ liệu đủ sạch và output trả lời được câu hỏi kỹ thuật.',doNotUseWhen:'Không dùng khi dữ liệu sai đơn vị, thiếu giả thiết hoặc output không thể kiểm chứng.',compactOutcome:'Nói được input, công thức, output, điều kiện sai và quyết định kỹ thuật.',applicationSteps:['Đặt biến từ tình huống thật.','Kiểm điều kiện áp dụng.','Tính hoặc mô phỏng output.','Diễn giải thành quyết định.'],analysisQuestions:['Đại lượng thật nào được mô hình hóa?','Input trong code là gì?','Điều kiện nào làm kết quả không đáng tin?']};
}
function e44List(xs,fallback,n=4){xs=arr(xs).map(v39TextFromAny).filter(Boolean); if(!xs.length)xs=fallback; return xs.slice(0,n).map(x=>`<li>${esc(e44Short(x,150))}</li>`).join('');}
function e44RenderApplicationStudy(){
 const C=e44AppContext(); const active=C.active||e44FallbackApp(C); const lesson=C.lesson||{}; const formula=active.formulaUsed||active.formula||active.coreFormula||e44CurrentLessonFormula(lesson);
 const progress=C.apps.length?Math.round(((C.idx+1)/C.apps.length)*100):100;
 return `<section class="panel learn-work-card e44-app-shell">
  <header class="e44-app-head"><div><span class="chip">🧩 ỨNG DỤNG · Lý thuyết → thực tế</span><h3>${esc(e44Short(active.title||'Ứng dụng thực tế',120))}</h3><p>${esc(e44Short(active.purpose||lesson.title||'Dùng trực tiếp nội dung lý thuyết vào đời sống, kỹ thuật và lập trình.',170))}</p></div><nav><button class="btn" data-act="e44-app-open-theory">Xem lại lý thuyết</button><button class="btn" data-act="e44-app-prev" ${C.idx<=0?'disabled':''}>← Case trước</button><button class="btn primary" data-act="e44-app-next" ${C.idx>=Math.max(0,C.apps.length-1)?'disabled':''}>Case sau →</button><button class="btn gold" data-act="e44-app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="e44-next-chapter-theory">Chương tiếp →</button></nav></header>
  <div class="e44-app-progress"><i style="width:${progress}%"></i><span>${C.apps.length?`${C.idx+1}/${C.apps.length}`:'auto'}</span></div>
  <section class="e44-app-anchor"><span>Lý thuyết dùng ở đây</span><h4>${esc(e44Short(formula,160))}</h4><p>${esc(e44Short(active.theoryAnchor||'Xác định biến, công thức, điều kiện áp dụng và ý nghĩa output trước khi đưa vào tình huống thật.',260))}</p></section>
  <section class="e44-app-grid"><article><b>Trong đời sống/kỹ thuật</b><p>${esc(e44Short(active.realLifeUse||active.realLifeScenario,260))}</p></article><article><b>Trong lập trình</b><p>${esc(e44Short(active.programmingUse,260))}</p></article></section>
  <section class="e44-app-when"><article><b>Khi nào dùng</b><p>${esc(e44Short(active.whenToUse,210))}</p></article><article><b>Khi nào không dùng</b><p>${esc(e44Short(active.doNotUseWhen,210))}</p></article><article><b>Output cần nói được</b><p>${esc(e44Short(active.compactOutcome||active.outputModel,230))}</p></article></section>
  <section class="e44-app-bottom"><article><h4>Quy trình ngắn</h4><ol>${e44List(active.applicationSteps,['Đặt biến từ tình huống thật.','Kiểm điều kiện áp dụng.','Tính hoặc mô phỏng output.','Diễn giải thành quyết định.'],4)}</ol></article><article><h4>Câu tự kiểm ứng dụng</h4><ol>${e44List(active.analysisQuestions,['Đại lượng thật nào được mô hình hóa?','Input trong code là gì?','Điều kiện nào làm kết quả không đáng tin?'],3)}</ol></article></section>
  <footer class="e44-app-footer"><div><span class="chip">Không phụ thuộc Bài tập</span><b>Ứng dụng trả lời: công thức dùng ở đâu?</b><p>Luồng chuẩn: Lý thuyết → Ứng dụng → Mô phỏng. Bài tập là nhánh luyện riêng, không kéo vào tab này.</p></div><nav><button class="btn" data-act="e44-app-open-theory">Xem lại lý thuyết</button><button class="btn gold" data-act="e44-app-open-sim">Mô phỏng tổng hợp</button><button class="btn green" data-act="e44-next-chapter-theory">Chương tiếp →</button></nav></footer>
 </section>`;
}
renderPractice=function(){return e44RenderApplicationStudy();};
const E44_PREV_PICKER=v39CompactPickerBar;
v39CompactPickerBar=function(mode,currentTitle,count,extra=''){ if(mode==='exercises'||mode==='practice')return ''; return E44_PREV_PICKER(mode,currentTitle,count,extra); };
document.addEventListener('click',function(e){
 const b=e.target.closest('button,[data-act]'); if(!b)return; const act=b.dataset.act||'';
 if(act==='e44-app-prev'||act==='e44-app-next'){e.preventDefault();e.stopPropagation();const C=e44AppContext();const d=act==='e44-app-next'?1:-1;state.practiceLineIndex=Math.max(0,Math.min(Math.max(0,C.apps.length-1),C.idx+d));save();render();return;}
 if(act==='e44-app-open-theory'){e.preventDefault();e.stopPropagation();const C=e44AppContext();state.view='learning';state.learnTab='theory';state.lessonId=C.lessonId;state.slide=0;save();render();toast('Đã mở lý thuyết tương ứng.');return;}
 if(act==='e44-app-open-sim'){e.preventDefault();e.stopPropagation();const C=e44AppContext();state.view='writing';state.simulationKind='unified';state.simulationTargetId=(C.active&& (C.active.id||C.active.lessonId))||C.lessonId;save();render();toast('Đã mở mô phỏng tổng hợp tương ứng.');return;}
 if(act==='e44-next-chapter-theory'){e.preventDefault();e.stopPropagation();const C=e44AppContext();const id=e36FirstLessonOfNextChapter(C.lessonId||C.lesson,1);e36GoTheoryToLesson(id);toast('Đã mở lý thuyết chương tiếp theo.');return;}
},true);
/* ===== END E44 ===== */


/* ===== E45 · simulation lab specialization + compact flow ===== */
function e45Text(x){return str(x||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e45Short(x,n=180){x=e45Text(x);return x.length<=n?x:x.slice(0,n).replace(/\s+\S*$/,'')+'…';}
function e45List(xs,fallback,n=5){xs=arr(xs).map(v39TextFromAny).filter(Boolean);if(!xs.length)xs=fallback;return xs.slice(0,n).map(x=>`<li>${esc(e45Short(x,180))}</li>`).join('');}
function e45SimKind(s){return mathSimKind?mathSimKind(s):(String(s?.type||s?.simKind||'').toLowerCase().includes('app')?'application':'theory');}
function e45SimPool(){const raw=byStage(arr(DB.simulations));const kind='unified';let pool=raw.filter(s=>e45SimKind(s)===kind);if(!pool.length)pool=raw;return {raw,kind,pool};}
function e45SimContext(){
 const P=e45SimPool(); let pool=P.pool; const q=e45Text(state.writingQuery||'').toLowerCase();
 if(q)pool=pool.filter(s=>e45Text([s.id,s.title,s.purpose,s.lessonId,s.chapterId,s.simulationProfile,s.formula,JSON.stringify(s.labNarrative||{})].join(' ')).toLowerCase().includes(q));
 const target=e45Text(state.simulationTargetId||''); let idx=0;
 if(target){const j=pool.findIndex(s=>[s.id,s.lessonId,s.targetId].map(e45Text).includes(target)); if(j>=0)idx=j; else idx=Math.min(Math.max(0,Number(state.writingIndex)||0),Math.max(0,pool.length-1));}
 else idx=Math.min(Math.max(0,Number(state.writingIndex)||0),Math.max(0,pool.length-1));
 return {...P,pool,idx,active:pool[idx]||pool[0]||{}};
}
function e45ModePanel(P){const raw=arr(DB.simulations);const t=raw.filter(s=>e45SimKind(s)==='theory').length;const a=raw.filter(s=>e45SimKind(s)==='application').length;const card=(kind,label,count)=>`<button class="e45-mode-card ${P.kind===kind?'active':''}" data-act="e45-sim-mode" data-kind="${kind}"><span>${kind==='theory'?'🔬':'🧩'}</span><b>${esc(label)}</b><small>${count} lab</small></button>`;return `<section class="e45-sim-modebar">${card('theory','Mô phỏng tổng hợp',t)}${card('application','Mô phỏng tổng hợp',a)}<div class="e45-mode-search"><input class="input" data-input="writingQuery" value="${esc(state.writingQuery||'')}" placeholder="Tìm lab, công thức, biến, profile..."></div></section>`;}
function e45Slider(v,i){const name=esc(v.name||('v'+i));const val=Number(v.default??v.value??0);return `<label class="e45-slider"><span><b>${esc(v.label||v.name||'Biến')}</b><i data-e45-val="${name}">${val}</i></span><input type="range" data-e45-range="${name}" min="${esc(v.min??0)}" max="${esc(v.max??10)}" step="${esc(v.step??0.1)}" value="${esc(val)}"><em>${esc(e45Short(v.effect||'Đổi biến và quan sát output.',110))}</em></label>`;}
function e45ScenarioButtons(sim){const items=arr(sim.labScenarios).slice(0,4);return `<div class="e45-scenarios">${items.map((x,i)=>`<button class="btn ${i===0?'primary':''}" data-act="e45-scenario" data-setup="${esc(x.setup||'')}" data-task="${esc(x.task||'')}">${esc(x.name||x.title||('Kịch bản '+(i+1)))}</button>`).join('')}</div>`;}
function e45Board(sim,kind){
 const model=sim.simulationModel||{}; const narrative=sim.labNarrative||{}; const vars=arr(sim.variables).slice(0,4); const read=arr(sim.computedReadouts).map(x=>x.label||x.meaning||x).slice(0,4);
 return `<section class="e45-lab-grid"><article class="e45-visual-card"><div class="e45-visual-head"><span class="chip">${esc(String(sim.simulationProfile||model.profile||kind).toUpperCase())}</span><b>${esc(model.visualMode||'interactive board')}</b></div><div class="e45-visual"><i></i><i></i><i></i><i></i><b>input → model → output</b></div><div class="e45-equation"><span>Công thức/model</span><pre>${esc(sim.formula||model.readoutFormula||'output = f(input)')}</pre></div></article><aside class="e45-control"><header><div><span class="chip">CONTROL</span><h3>Đổi biến có kiểm soát</h3></div><button class="btn" data-act="e45-reset">Baseline</button></header>${vars.length?vars.map(e45Slider).join(''):'<p>Chưa có biến điều khiển.</p>'}${e45ScenarioButtons(sim)}</aside></section><section class="e45-readout"><article><span class="chip">ĐỌC OUTPUT</span><h4>${esc(e45Short(narrative.whatToConclude||model.interpretation||'Đọc output, kiểm điều kiện rồi kết luận.',170))}</h4><ul>${e45List(read,['Output đổi theo biến nào?','Điều kiện còn đúng không?','Kết luận dùng được đến đâu?'],4)}</ul></article><article><span class="chip">ỨNG DỤNG / CODE</span><h4>${esc(e45Short(narrative.realUse||sim.purpose||'Mô phỏng nối công thức với tình huống thật.',170))}</h4><p>${esc(e45Short(narrative.programmingBridge||'Trong code: tạo input, chạy model, log output và cảnh báo điều kiện áp dụng.',260))}</p></article></section>`;
}
function e45SimFlow(C){return `<footer class="e45-sim-flow"><div><span class="chip">LAB FLOW</span><b>${C.kind==='application'?'Lý thuyết → Ứng dụng → Mô phỏng':'Lý thuyết → Mô phỏng → Bài tập'}</b><p>Chạy lab xong phải ghi được input, công thức, output, điều kiện và kết luận kỹ thuật.</p></div><nav><button class="btn" data-act="e45-open-theory">Xem lý thuyết</button><button class="btn" data-act="e45-sim-prev" ${C.idx<=0?'disabled':''}>← Lab trước</button><button class="btn primary" data-act="e45-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>Lab sau →</button><button class="btn green" data-act="e44-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
renderMathSimulationWorkspace=function(){
 const C=e45SimContext(); const sim=C.active||{}; const src=sim.file||((C.kind==='application')?'simulations/unified_lab.html':'simulations/unified_lab.html'); const progress=C.pool.length?Math.round(((C.idx+1)/C.pool.length)*100):100;
 return `<div class="mathlab-shell e45-sim-shell ${C.kind==='application'?'mode-application':'mode-theory'}">${e45ModePanel(C)}<main class="panel e45-sim-main"><header class="e45-sim-head"><div><span class="chip">Mô phỏng tổng hợp · ${esc(sim.lessonId||sim.id||'SIM')}</span><h3>${esc(e45Short(sim.title||'Lab mô phỏng',150))}</h3><p>${esc(e45Short(sim.purpose||'Đổi tham số và đọc output theo điều kiện áp dụng.',230))}</p></div><nav><button class="btn" data-act="e45-sim-prev" ${C.idx<=0?'disabled':''}>←</button><button class="btn primary" data-act="e45-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>→</button></nav></header><div class="e45-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.pool.length||1}</span></div>${e45Board(sim,C.kind)}<section class="e45-lab-notes"><article><h4>Checklist diễn giải</h4><ul>${e45List(sim.interpretationChecklist,['Input là gì?','Công thức nào tạo output?','Điều kiện nào bị phá?'],5)}</ul></article><article><h4>Mẫu báo cáo</h4><ol>${e45List(sim.reportTemplate,['Baseline: ...','Biến chi phối: ...','Kết luận kỹ thuật: ...'],5)}</ol></article><article><h4>Pseudocode</h4><ol>${e45List(sim.pseudoCode,['load input','set baseline','change one variable','compare output','conclude'],5)}</ol></article></section><details class="e45-iframe"><summary>Khung lab nền / iframe</summary><iframe class="mathlab-frame" src="${esc(src)}" loading="lazy"></iframe></details>${e45SimFlow(C)}</main></div>`;
};
document.addEventListener('input',function(e){const r=e.target&&e.target.matches('[data-e45-range]')?e.target:null;if(!r)return;const box=r.closest('.e45-sim-shell');if(!box)return;const name=r.dataset.e45Range;const out=box.querySelector(`[data-e45-val="${CSS.escape(name)}"]`);if(out)out.textContent=r.value;},true);
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]');if(!b)return;const act=b.dataset.act||'';if(act==='e45-sim-mode'){e.preventDefault();e.stopPropagation();state.simulationKind=b.dataset.kind==='application'?'application':'theory';state.writingIndex=0;state.simulationTargetId='';save();render();return;}if(act==='e45-sim-prev'||act==='e45-sim-next'){e.preventDefault();e.stopPropagation();const C=e45SimContext();const d=act==='e45-sim-next'?1:-1;state.writingIndex=Math.max(0,Math.min(Math.max(0,C.pool.length-1),C.idx+d));state.simulationTargetId='';save();render();return;}if(act==='e45-open-theory'){e.preventDefault();e.stopPropagation();const C=e45SimContext();state.view='learning';state.learnTab='theory';state.lessonId=C.active.lessonId||state.lessonId;state.slide=0;save();render();toast('Đã mở lý thuyết tương ứng.');return;}if(act==='e45-reset'){e.preventDefault();e.stopPropagation();const root=b.closest('.e45-sim-shell');if(root)root.querySelectorAll('[data-e45-range]').forEach(r=>{r.value=r.getAttribute('value')||r.value;r.dispatchEvent(new Event('input',{bubbles:true}));});return;}if(act==='e45-scenario'){e.preventDefault();e.stopPropagation();toast((b.dataset.setup||'Kịch bản')+' → '+(b.dataset.task||'Ghi kết luận.'));return;}},true);
/* ===== END E45 ===== */


/* ===== E46 · active simulation readout + application bridge QA ===== */
function e46Num(x,d=0){x=Number(x);return Number.isFinite(x)?x:d;}
function e46Clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function e46SafeText(x){return str(x||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e46Short(x,n=180){x=e46SafeText(x);return x.length<=n?x:x.slice(0,n).replace(/\s+\S*$/,'')+'…';}
function e46List(xs,fallback,n=5){xs=arr(xs).map(v39TextFromAny).filter(Boolean);if(!xs.length)xs=fallback;return xs.slice(0,n).map(x=>`<li>${esc(e46Short(x,170))}</li>`).join('');}
function e46SimKind(s){return (String(s?.type||s?.simKind||'').toLowerCase().includes('app')||String(s?.group||'').toLowerCase().includes('ứng dụng'))?'application':'theory';}
function e46SimContext(){
 const raw=byStage(arr(DB.simulations)); const kind='unified'; let pool=raw.filter(s=>e46SimKind(s)===kind); if(!pool.length)pool=raw;
 const q=e46SafeText(state.writingQuery||'').toLowerCase();
 if(q)pool=pool.filter(s=>e46SafeText([s.id,s.lessonId,s.title,s.purpose,s.chapterId,s.simulationProfile,JSON.stringify(s.lessonBridge||{})].join(' ')).toLowerCase().includes(q));
 const target=e46SafeText(state.simulationTargetId||state.lessonId||''); let idx=0;
 if(target){let j=pool.findIndex(s=>[s.id,s.lessonId,s.targetId,s.chapterId].map(e46SafeText).includes(target)); if(j<0)j=pool.findIndex(s=>e46SafeText(s.lessonId).includes(target)||e46SafeText(target).includes(s.lessonId)); if(j>=0)idx=j; else idx=Math.min(Math.max(0,Number(state.writingIndex)||0),Math.max(0,pool.length-1));}
 else idx=Math.min(Math.max(0,Number(state.writingIndex)||0),Math.max(0,pool.length-1));
 return {raw,kind,pool,idx,active:pool[idx]||pool[0]||{}};
}
function e46VarValue(v,i){const d=e46Num(v.default??v.value??0.5,0.5);return e46Clamp(d,0,1);}
function e46ComputeFromVars(vars){
 const named={}; arr(vars).forEach((v,i)=>{named[v.name||('v'+i)]=e46VarValue(v,i);});
 const signal=e46Num(named.signal??named.input??named.strength??Object.values(named)[0],0.62);
 const noise=e46Num(named.noise??named.error??Object.values(named)[1],0.18);
 const scale=e46Num(named.scale??named.condition??named.regularization??Object.values(named)[2],0.35);
 const threshold=e46Num(named.threshold??Object.values(named)[3],0.55);
 const score=e46Clamp(Math.round(55+22*signal-20*noise+12*(1-Math.abs(scale-0.35))-10*Math.abs(threshold-0.5)),0,100);
 const stability=e46Clamp(Math.round(72-36*noise-18*scale+12*signal),0,100);
 const confidence=e46Clamp(Math.round((score+stability)/2),0,100);
 const decision=(score>=threshold*100&&stability>=55)?'PASS':(stability<45||noise>0.65?'RISK':'REVIEW');
 return {signal,noise,scale,threshold,score,stability,confidence,decision};
}
function e46ModeBar(C){return '';}
function e46Slider(v,i){const name=esc(v.name||('v'+i));const val=e46VarValue(v,i);return `<label class="e46-slider"><span><b>${esc(v.label||v.name||'Biến')}</b><i data-e46-val="${name}">${val.toFixed(2)}</i></span><input type="range" data-e46-range="${name}" min="0" max="1" step="0.01" value="${esc(val)}"><em>${esc(e46Short(v.effect||'Đổi biến để quan sát output.',120))}</em></label>`;}
function e46ReadoutPanel(sim){const m=e46ComputeFromVars(sim.variables);const spec=sim.liveComputationSpec||{};const labels=arr(spec.readouts).length?arr(spec.readouts):['Score','Stability','Decision'];return `<section class="e46-readouts" data-e46-readouts="1"><article><span>Score</span><b data-e46-score>${m.score}</b><i>/100</i></article><article><span>Stability</span><b data-e46-stability>${m.stability}</b><i>/100</i></article><article><span>Confidence</span><b data-e46-confidence>${m.confidence}</b><i>/100</i></article><article class="decision ${String(m.decision).toLowerCase()}"><span>Decision</span><b data-e46-decision>${m.decision}</b><i>${esc(labels.slice(0,2).join(' · '))}</i></article></section>`;}
function e46PresetButtons(sim){const presets=arr(sim.stressPresets).slice(0,4);return `<div class="e46-presets">${presets.map((p,i)=>`<button class="btn ${i===0?'primary':''}" data-act="e46-preset" data-values="${esc(JSON.stringify(p.values||{}))}" data-task="${esc(p.task||'Đọc output và ghi kết luận.')}">${esc(p.name||('Preset '+(i+1)))}</button>`).join('')}</div>`;}
function e46LabBoard(sim,C){const vars=arr(sim.variables).slice(0,4);const bridge=sim.lessonBridge||{};const spec=sim.liveComputationSpec||{};const src=C.kind==='application'?'Lý thuyết → Ứng dụng → Mô phỏng':'Lý thuyết → Mô phỏng → Bài tập';return `<section class="e46-lab-board"><article class="e46-model-card"><div><span class="chip">${esc(String(sim.simulationProfile||spec.profile||'LAB').toUpperCase())}</span><h3>${esc(e46Short(sim.title||'Lab mô phỏng',135))}</h3><p>${esc(e46Short(sim.purpose||'Đổi biến và đọc output theo điều kiện áp dụng.',210))}</p></div><pre>${esc(spec.formula||sim.formula||'output = f(input)')}</pre><small>${esc(src)}</small></article><aside class="e46-controls"><header><b>Điều khiển biến</b><button class="btn" data-act="e46-reset">Baseline</button></header>${vars.map(e46Slider).join('')}${e46PresetButtons(sim)}</aside></section>${e46ReadoutPanel(sim)}<section class="e46-bridge-grid"><article><b>Từ lý thuyết</b><p>${esc(e46Short(bridge.theoryTitle||sim.lessonId||'Bài học hiện tại',190))}</p><code>${esc(e46Short(bridge.theoryFormula||sim.formula||'',180))}</code></article><article><b>Dùng trong thực tế/code</b><p>${esc(e46Short((C.kind==='application'?bridge.realUse:bridge.programmingUse)||sim.purpose,260))}</p></article><article><b>Cảnh báo đọc sai</b><ul>${e46List(sim.commonMisreadings,['Score cao không có nghĩa điều kiện đúng.','Đổi nhiều biến cùng lúc làm mất nguyên nhân.'],3)}</ul></article></section>`;}
function e46Notes(sim){return `<section class="e46-notes"><article><h4>Checklist</h4><ul>${e46List(sim.interpretationChecklist,['Input là gì?','Công thức nào tạo output?','Điều kiện nào bị phá?'],5)}</ul></article><article><h4>Báo cáo lab</h4><ol>${e46List(sim.reportTemplate,['Input: ...','Output: ...','Kết luận: ...'],5)}</ol></article><article><h4>Pseudocode</h4><ol>${e46List(sim.pseudoCode,['load input','set vars','compute readouts','compare','conclude'],5)}</ol></article></section><section class="e46-report-box"><label><b>Ghi kết luận nhanh</b><textarea class="textarea compact-textarea" data-e46-report placeholder="Ví dụ: Khi noise tăng từ 0.18 lên 0.72, stability giảm nên kết luận phải chuyển từ PASS sang REVIEW/RISK..."></textarea></label><button class="btn" data-act="e46-fill-report">Tạo mẫu kết luận</button></section>`;}
function e46Flow(C){return `<footer class="e46-flow"><div><span class="chip">FLOW</span><b>${C.kind==='application'?'Lý thuyết → Ứng dụng → Lab':'Lý thuyết → Lab → Bài tập'}</b><p>Lab chỉ đạt khi đọc được input, công thức, output, điều kiện và quyết định.</p></div><nav><button class="btn" data-act="e46-open-theory">Xem lý thuyết</button><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>← Lab trước</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>Lab sau →</button><button class="btn green" data-act="e44-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
renderMathSimulationWorkspace=function(){const C=e46SimContext();const sim=C.active||{};const progress=C.pool.length?Math.round(((C.idx+1)/C.pool.length)*100):100;return `<div class="mathlab-shell e46-sim-shell mode-${esc(C.kind)}">${e46ModeBar(C)}<main class="panel e46-sim-main"><header class="e46-head"><div><span class="chip">E46 ACTIVE LAB · MÔ PHỎNG TỔNG HỢP</span><h3>${esc(e46Short(sim.title||'Lab mô phỏng',145))}</h3></div><nav><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>←</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>→</button></nav></header><div class="e46-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.pool.length||1}</span></div>${e46LabBoard(sim,C)}${e46Notes(sim)}${e46Flow(C)}</main></div>`;};
function e46UpdateReadouts(root){const vars=[];root.querySelectorAll('[data-e46-range]').forEach(r=>{vars.push({name:r.dataset.e46Range,default:Number(r.value)});const out=root.querySelector(`[data-e46-val="${CSS.escape(r.dataset.e46Range)}"]`);if(out)out.textContent=Number(r.value).toFixed(2);});const m=e46ComputeFromVars(vars);const set=(sel,val)=>{const el=root.querySelector(sel);if(el)el.textContent=val;};set('[data-e46-score]',m.score);set('[data-e46-stability]',m.stability);set('[data-e46-confidence]',m.confidence);set('[data-e46-decision]',m.decision);const d=root.querySelector('.e46-readouts .decision');if(d)d.className='decision '+String(m.decision).toLowerCase();}
document.addEventListener('input',function(e){const r=e.target&&e.target.matches('[data-e46-range]')?e.target:null;if(!r)return;const root=r.closest('.e46-sim-shell');if(root)e46UpdateReadouts(root);},true);
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]');if(!b)return;const act=b.dataset.act||'';if(act==='e46-sim-mode'){e.preventDefault();e.stopPropagation();state.simulationKind=b.dataset.kind==='application'?'application':'theory';state.writingIndex=0;state.simulationTargetId=state.lessonId||'';save();render();return;}if(act==='e46-sim-prev'||act==='e46-sim-next'){e.preventDefault();e.stopPropagation();const C=e46SimContext();const d=act==='e46-sim-next'?1:-1;state.writingIndex=Math.max(0,Math.min(Math.max(0,C.pool.length-1),C.idx+d));state.simulationTargetId='';save();render();return;}if(act==='e46-open-theory'){e.preventDefault();e.stopPropagation();const C=e46SimContext();state.view='learning';state.learnTab='theory';state.lessonId=C.active.lessonId||state.lessonId;state.slide=0;save();render();toast('Đã mở lý thuyết tương ứng.');return;}if(act==='e46-reset'){e.preventDefault();e.stopPropagation();const root=b.closest('.e46-sim-shell');if(root){root.querySelectorAll('[data-e46-range]').forEach(r=>{r.value=r.getAttribute('value')||r.defaultValue||0.5;});e46UpdateReadouts(root);}return;}if(act==='e46-preset'){e.preventDefault();e.stopPropagation();const root=b.closest('.e46-sim-shell');if(root){let vals={};try{vals=JSON.parse(b.dataset.values||'{}')}catch(_){vals={}}root.querySelectorAll('[data-e46-range]').forEach(r=>{if(vals[r.dataset.e46Range]!=null)r.value=vals[r.dataset.e46Range];});e46UpdateReadouts(root);toast(b.dataset.task||'Đã áp kịch bản.');}return;}if(act==='e46-fill-report'){e.preventDefault();e.stopPropagation();const root=b.closest('.e46-sim-shell');if(!root)return;e46UpdateReadouts(root);const txt=root.querySelector('[data-e46-report]');const score=root.querySelector('[data-e46-score]')?.textContent||'';const st=root.querySelector('[data-e46-stability]')?.textContent||'';const dec=root.querySelector('[data-e46-decision]')?.textContent||'';if(txt)txt.value=`Input đã thay đổi theo kịch bản. Score=${score}/100, Stability=${st}/100, Decision=${dec}. Kết luận: chỉ dùng kết quả khi điều kiện áp dụng còn đúng và nhiễu/scale không phá giả thiết.`;return;}if(act==='e44-app-open-sim'){setTimeout(()=>{try{const C=e44AppContext();state.view='writing';state.simulationKind='unified';state.simulationTargetId=C.lessonId||state.lessonId||'';state.writingIndex=0;save();render();toast('Đã mở lab ứng dụng đúng bài lý thuyết.');}catch(_){}} ,0);return;}},true);
/* ===== END E46 ===== */


/* ===== E47 · Formula tab role repair + deep formula differentiation ===== */
function e47Plain(s){return str(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e47Short(s,n=220){s=e47Plain(s);return s.length<=n?s:s.slice(0,n).replace(/\s+\S*$/,'')+'…';}
function e47Info(item){const info=e38FormulaInfo?e38FormulaInfo(item):v34FormulaInfo(item);return Object.assign({},info,{functionMeaning:item?.functionMeaning||info.meaning,formulaParts:arr(item?.formulaParts),realUse:item?.realUse||item?.application||item?.usage||info.example,programmingUse:item?.programmingUse||item?.codeUse||'Trong code: đặt input, kiểm shape/đơn vị, tính output, log sai số và diễn giải kết quả.',whenToUse:item?.whenToUse||arr(info.conditions)[0]||'Dùng khi giả thiết và điều kiện áp dụng đúng.',doNotUseWhen:item?.doNotUseWhen||arr(info.mistakes)[0]||'Không dùng khi dữ kiện thiếu, sai đơn vị hoặc giả thiết bị phá vỡ.',deepSystemRole:item?.deepSystemRole||'Công thức là cầu nối Lý thuyết → Ứng dụng → Mô phỏng: xác định input, phép biến đổi, output và tiêu chí đọc kết quả.',implementationSteps:arr(item?.implementationSteps).length?arr(item.implementationSteps):['Đọc biến và đơn vị đo.','Kiểm điều kiện áp dụng.','Tính hoặc mô phỏng output.','So sánh với baseline/ngưỡng.','Viết kết luận có điều kiện.']});}
function e47FormulaPartsHtml(parts){parts=arr(parts).slice(0,5);if(!parts.length)parts=[{symbol:'input',function:'dữ kiện ban đầu'},{symbol:'operator',function:'phép biến đổi toán học'},{symbol:'output',function:'kết quả để ra quyết định'}];return parts.map(p=>`<li><b>${esc(p.symbol||p.name||'thành phần')}</b><span>${esc(p.function||p.role||p.meaning||'vai trò trong công thức')}</span></li>`).join('');}
function e47ConditionsHtml(xs,fallback){xs=arr(xs).map(v39TextFromAny).filter(Boolean);if(!xs.length)xs=fallback;return xs.slice(0,5).map(x=>`<li>${esc(e47Short(x,160))}</li>`).join('');}
function e47FormulaNavLine(kind){return `<nav class="e47-formula-navline">${e36FormulaNav(kind)}<button class="btn" data-learn="theory">Xem lý thuyết</button><button class="btn gold" data-act="e37-open-sim-theory">Mô phỏng</button></nav>`;}
function e47FormulaTop(kind,info,item,queryName,pickerAct){const meta=v33ResourceMeta(item);const isDeep=kind==='grammar';return `<section class="panel e47-formula-top"><div><span class="chip">${isDeep?'∑ CÔNG THỨC SÂU':'🧮 CÔNG THỨC'} · ${esc(stageTitle(meta.stage||state.stage))}</span><h3>${isDeep?'Vai trò hệ thống và điều kiện dùng':'Thẻ công thức và phân tích chức năng'}</h3><p>${esc(v35FormulaChapterLabel(item))}</p></div><div class="e47-formula-tools"><input class="input" data-input="${esc(queryName)}" value="${esc(isDeep?(state.grammarQuery||''):(state.vocabQuery||''))}" placeholder="Tìm công thức, điều kiện, ứng dụng...">${e47FormulaNavLine(kind)}<button class="btn primary" data-act="${esc(pickerAct)}">☷ Chọn chương</button></div></section>`;}
function e47FormulaBack(info){return `<div class="v1310-flash-face v1312-flash-face flipped e47-flash-back"><span>Phân tích sâu công thức</span><div class="meaning"><b>Tác dụng:</b> ${esc(e47Short(info.functionMeaning||info.meaning,190))}</div><ul class="e47-mini-parts">${e47FormulaPartsHtml(info.formulaParts)}</ul></div>`;}
function renderVocab(){
 try{
  const list=getVocab(); if(!list.length)return `<section class="panel vocab-empty learning-recovery-card"><span class="chip">🧮 Công thức</span><h3>Chưa có công thức phù hợp</h3><p>Đổi giai đoạn hoặc xóa từ khóa tìm kiếm.</p></section>`;
  state.vocabIndex=Math.min(Math.max(0,Number(state.vocabIndex)||0),Math.max(0,list.length-1));
  const v=list[state.vocabIndex]||list[0]||{}; const info=e47Info(v); const flipped=!!state.vocabFlipped;
  const cond=e47ConditionsHtml(info.conditions,['Kiểm giả thiết, kích thước và miền giá trị trước khi thay số.']);
  const mis=e47ConditionsHtml(info.mistakes,['Không dùng công thức khi chưa kiểm tra điều kiện áp dụng.']);
  const front=`<div class="v1310-flash-face v1312-flash-face e47-flash-front"><span class="chip">Công thức trọng tâm</span><div class="term term-xlong formula-flash-term">${esc(info.formula||info.title)}</div><div class="v1310-pron">↺ Lật thẻ để phân tích sâu công thức</div></div>`;
  const back=e47FormulaBack(info);
  return `<div class="vocab-studio formula-v35-shell e36-formula-shell e47-formula-shell">
   ${e47FormulaTop('vocab',info,v,'vocabQuery','open-formula-picker')}
   <main class="panel vocab-card-panel formula-v35-main e36-formula-main e47-formula-main">
    <header class="e47-card-head"><div><span class="chip">${esc(v.lessonId||v.chapterId||'FORMULA')}</span><h3>${esc(info.title)}</h3><p>${esc(info.formula||'')}</p></div><b>${state.vocabIndex+1}/${list.length}</b></header>
    <button class="flash visual-flash v1310-flash formula-v34-flash e47-formula-flash ${flipped?'flipped':''}" data-act="toggle-vocab-flip"><div class="flash-inner v1310-flash-inner">${flipped?back:front}</div></button>
    <div class="vocab-actions v1310-vocab-actions e47-formula-actions"><button class="btn" data-act="prev-vocab">← Mục trước</button><button class="btn primary" data-act="toggle-vocab-flip">${flipped?'Mặt công thức':'Lật phân tích sâu'}</button><button class="btn" data-act="next-vocab">Mục sau →</button></div>
    <section class="e47-formula-analysis-grid"><article class="main"><b>Tác dụng của công thức</b><p>${esc(e47Short(info.functionMeaning||info.meaning,260))}</p></article><article><b>Từng phần chức năng</b><ul>${e47FormulaPartsHtml(info.formulaParts)}</ul></article><article><b>Dùng trong thực tế/code</b><p>${esc(e47Short(info.realUse||info.example,190))}</p><p>${esc(e47Short(info.programmingUse,190))}</p></article></section>
    <section class="e47-formula-guard"><article><b>Điều kiện dùng</b><ul>${cond}</ul></article><article><b>Không dùng / lỗi dễ mắc</b><ul>${mis}</ul></article></section>
    ${e37FormulaFlowFooter('vocab')}
   </main>
  </div>`;
 }catch(e){console.error('FORMULA_RENDER_GUARD_E47',e);return `<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI CÔNG THỨC</span><h3>Không render được tab Công thức</h3><p>${esc(e?.message||e)}</p></section>`;}
}
function e47DeepRoleCard(info,item){const steps=e47ConditionsHtml(info.implementationSteps,['Đọc input.','Kiểm điều kiện.','Tính output.','Đọc sai số.','Kết luận.']);return `<section class="e47-deep-role"><article class="main"><span class="chip">VAI TRÒ TRONG HỆ THỐNG</span><h3>${esc(e47Short(info.title,140))}</h3><p>${esc(e47Short(info.deepSystemRole,340))}</p></article><article><b>Pipeline triển khai</b><ol>${steps}</ol></article></section>`;}
function renderGrammar(){
 try{
  const xs=grammarDeepItems(); if(!xs.length)return `<section class="panel learning-recovery-card"><span class="chip">∑ Công thức sâu</span><h3>Chưa có dữ liệu công thức sâu</h3><p>Hãy kiểm tra formulas.json hoặc grammar-path.json.</p></section>`;
  state.grammarIndex=Math.min(Math.max(0,Number(state.grammarIndex)||0),Math.max(0,xs.length-1)); const g=xs[state.grammarIndex]||xs[0]||{}; const info=e47Info(g);
  const cond=e47ConditionsHtml(info.conditions,['Kiểm giả thiết, kích thước và miền giá trị.']); const mis=e47ConditionsHtml(info.mistakes,['Không nhầm công thức với quy trình tính số trên máy.']); const related=arr(g.conceptIds).slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>concept</span>';
  return `<div class="grammar-luxe-shell formula-deep-v35-shell e36-formula-shell e47-formula-shell e47-deep-shell">
   ${e47FormulaTop('grammar',info,g,'grammarQuery','open-grammar-picker')}
   <main class="panel grammar-main-card formula-deep-main e47-formula-main e47-deep-main">
    <header class="e47-card-head e47-deep-head"><div><span class="chip">${esc(g.lessonId||g.chapterId||'DEEP')}</span><h3>Công thức sâu = kiểm giả thiết + vai trò hệ thống</h3><p>${esc(info.formula||g.rule||'')}</p></div><b>${state.grammarIndex+1}/${xs.length}</b></header>
    ${e47DeepRoleCard(info,g)}
    <section class="e47-deep-grid"><article><b>Cấu trúc công thức</b><ul>${e47FormulaPartsHtml(info.formulaParts)}</ul></article><article><b>Điều kiện áp dụng</b><ul>${cond}</ul></article><article><b>Dấu hiệu đọc sai</b><ul>${mis}</ul></article></section>
    <section class="e47-deep-bridge"><article><b>Trong lập trình/mô phỏng</b><p>${esc(e47Short(info.programmingUse,260))}</p></article><article><b>Khi nào dùng</b><p>${esc(e47Short(info.whenToUse,220))}</p></article><article><b>Khi nào không dùng</b><p>${esc(e47Short(info.doNotUseWhen,220))}</p></article></section>
    <footer class="grammar-footer e47-concepts"><div><b>Concept liên quan</b><div class="formula-concept-tags">${related}</div></div></footer>
    ${e37FormulaFlowFooter('grammar')}
   </main>
  </div>`;
 }catch(e){console.error('GRAMMAR_RENDER_GUARD_E47',e);return `<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI CÔNG THỨC SÂU</span><h3>Không render được tab Công thức sâu</h3><p>${esc(e?.message||e)}</p></section>`;}
}
/* ===== END E47 ===== */

/* ===== E48 · Deep Formula System Audit ===== */
function e48ListHtml(xs,limit=5){xs=arr(xs).map(v39TextFromAny).filter(Boolean);return xs.slice(0,limit).map(x=>`<li>${esc(e47Short(x,190))}</li>`).join('')||'<li>Chưa có mục kiểm định.</li>';}
function e48DeepInfo(item){const info=e47Info(item);return Object.assign({},info,{deepProfile:item?.deepProfile||'general',deepRoleStatement:item?.deepRoleStatement||info.deepSystemRole,deepAssumptionGates:arr(item?.deepAssumptionGates),deepDerivationSketch:arr(item?.deepDerivationSketch),deepSensitivityChecklist:arr(item?.deepSensitivityChecklist),deepFailureModes:arr(item?.deepFailureModes),deepSystemPipeline:arr(item?.deepSystemPipeline),deepDebugQuestions:arr(item?.deepDebugQuestions),deepDefensePoints:arr(item?.deepDefensePoints),deepMiniExperiment:item?.deepMiniExperiment||{},deepFormulaTakeaway:item?.deepFormulaTakeaway||'Công thức sâu dùng để kiểm giả thiết, độ nhạy, lỗi triển khai và quyết định dùng/không dùng trong hệ thống.'});}
function e48ProfileLabel(p){return ({linear:'Linear Algebra',probability:'Probability/Statistics',time_series:'Time Series',signal:'Signal Processing',optimization:'Optimization',system:'System/Control',research:'NIR/VKR Research',russian_math:'Russian Math',general:'General Math'})[p]||'System Audit';}
function e48MetricPills(info){const items=[['Profile',e48ProfileLabel(info.deepProfile)],['Gates',arr(info.deepAssumptionGates).length],['Sensitivity',arr(info.deepSensitivityChecklist).length],['Failure modes',arr(info.deepFailureModes).length],['Pipeline',arr(info.deepSystemPipeline).length]];return `<section class="e48-audit-pills">${items.map(x=>`<article><b>${esc(x[0])}</b><span>${esc(x[1])}</span></article>`).join('')}</section>`;}
function e48MiniExperimentHtml(m){m=m&&typeof m==='object'?m:{};const rows=[['Mục tiêu',m.goal],['Input',m.input],['Thao tác',m.operation],['Readout',m.readout],['Báo cáo',m.report]].filter(x=>x[1]);return `<section class="e48-mini-exp"><div><span class="chip">MINI LAB · kiểm công thức</span><h4>Đưa công thức vào thử nghiệm nhỏ</h4><p>Không chỉ nhìn công thức, phải kiểm output đổi ra sao khi dữ liệu bị nhiễu, đổi scale hoặc đổi giả thiết.</p></div><ol>${rows.length?rows.map(x=>`<li><b>${esc(x[0])}</b><span>${esc(x[1])}</span></li>`).join(''):'<li><b>Thử nghiệm</b><span>Chọn ví dụ nhỏ, đổi một tham số, đọc output và ghi kết luận.</span></li>'}</ol></section>`;}
function e48DeepTop(info,item){const meta=v33ResourceMeta(item);return `<section class="panel e48-deep-top"><div><span class="chip">∑ CÔNG THỨC SÂU · ${esc(stageTitle(meta.stage||state.stage))}</span><h3>Audit công thức trong hệ thống</h3><p>${e38CleanChapterLabel(item)} · ${esc(e48ProfileLabel(info.deepProfile))}</p></div><div class="e48-deep-tools"><input class="input" data-input="grammarQuery" value="${esc(state.grammarQuery||'')}" placeholder="Tìm công thức, giả thiết, lỗi, pipeline...">${e47FormulaNavLine('grammar')}<button class="btn primary" data-act="open-grammar-picker">☷ Chọn chương</button></div></section>`;}
function e48DeepRoleHero(info,item){return `<section class="e48-deep-hero"><article class="main"><span class="chip">VAI TRÒ RIÊNG CỦA TAB CÔNG THỨC SÂU</span><h3>${esc(e47Short(info.title,150))}</h3><p>${esc(e47Short(info.deepRoleStatement,420))}</p><pre>${esc(info.formula||item?.rule||'')}</pre></article><article><b>Công thức sâu khác gì Công thức?</b><p><b>Công thức</b> giúp nhớ ký hiệu và chức năng từng phần. <b>Công thức sâu</b> kiểm xem công thức có được phép dùng trong hệ thống thật không, nhạy với dữ liệu nào, lỗi triển khai nào có thể làm kết luận sai.</p></article></section>`;}
function e48FlowMap(info){const pipeline=e48ListHtml(info.deepSystemPipeline,5);return `<section class="e48-flow-map"><div><span class="chip">Lý thuyết → Ứng dụng → Mô phỏng</span><h4>Đường đi của công thức trong hệ thống</h4></div><ol>${pipeline}</ol></section>`;}
function e48FormulaDeepFooter(){return `<footer class="e48-deep-footer"><div><span class="chip">ĐỌC SÂU → KIỂM → CHẠY LAB</span><b>Đừng dừng ở việc thuộc công thức</b><p>Sau khi kiểm giả thiết, hãy mở mô phỏng để xem biến đầu vào làm output đổi như thế nào.</p></div><nav><button class="btn" data-view="vocab">Xem thẻ công thức</button><button class="btn" data-learn="theory">Xem lý thuyết</button><button class="btn gold" data-act="e37-open-sim-theory">Mô phỏng kiểm công thức</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
renderGrammar=function(){
 try{
  const xs=grammarDeepItems(); if(!xs.length)return `<section class="panel learning-recovery-card"><span class="chip">∑ Công thức sâu</span><h3>Chưa có dữ liệu công thức sâu</h3><p>Hãy kiểm tra formulas.json hoặc grammar-path.json.</p></section>`;
  state.grammarIndex=Math.min(Math.max(0,Number(state.grammarIndex)||0),Math.max(0,xs.length-1)); const g=xs[state.grammarIndex]||xs[0]||{}; const info=e48DeepInfo(g); const related=arr(g.conceptIds).slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>concept</span>';
  return `<div class="grammar-luxe-shell formula-deep-v35-shell e36-formula-shell e47-formula-shell e48-deep-shell">
   ${e48DeepTop(info,g)}
   <main class="panel grammar-main-card formula-deep-main e48-deep-main">
    <header class="e48-deep-head"><div><span class="chip">${esc(g.lessonId||g.chapterId||'DEEP')}</span><h3>Công thức sâu = audit giả thiết + độ nhạy + lỗi triển khai</h3><p>${esc(info.deepFormulaTakeaway)}</p></div><b>${state.grammarIndex+1}/${xs.length}</b></header>
    ${e48MetricPills(info)}
    ${e48DeepRoleHero(info,g)}
    <section class="e48-audit-grid"><article class="gate"><b>1 · Cổng giả thiết</b><ul>${e48ListHtml(info.deepAssumptionGates,5)}</ul></article><article><b>2 · Vì sao công thức hoạt động</b><ol>${e48ListHtml(info.deepDerivationSketch,5)}</ol></article><article><b>3 · Độ nhạy cần thử</b><ul>${e48ListHtml(info.deepSensitivityChecklist,5)}</ul></article><article class="risk"><b>4 · Khi nào kết luận sai</b><ul>${e48ListHtml(info.deepFailureModes,5)}</ul></article></section>
    ${e48FlowMap(info)}
    <section class="e48-debug-board"><article><b>Câu hỏi debug</b><ol>${e48ListHtml(info.deepDebugQuestions,5)}</ol></article><article><b>Điểm cần nói khi vấn đáp/bảo vệ</b><ul>${e48ListHtml(info.deepDefensePoints,5)}</ul></article><article><b>Concept liên quan</b><div class="formula-concept-tags">${related}</div></article></section>
    ${e48MiniExperimentHtml(info.deepMiniExperiment)}
    ${e48FormulaDeepFooter()}
   </main>
  </div>`;
 }catch(e){console.error('GRAMMAR_RENDER_GUARD_E48',e);return `<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI CÔNG THỨC SÂU</span><h3>Không render được tab Công thức sâu</h3><p>${esc(e?.message||e)}</p></section>`;}
};
/* ===== END E48 ===== */



/* ===== E49 · Simulation Deduplication + Chapter-Specific Lab Renderer ===== */
window.__E49_SIM_DEDUP_SPECIALIZATION__ = true;
function e49Safe(v){try{return v39TextFromAny?v39TextFromAny(v):String(v??'');}catch(_){return String(v??'');}}
function e49List(xs,limit){xs=arr(xs).map(e49Safe).filter(Boolean);return xs.slice(0,limit||5).map(x=>`<li>${esc(e46Short(x,210))}</li>`).join('')||'<li>Chưa có dữ liệu chuyên biệt.</li>';}
function e49ScenarioList(sim){return arr(sim.labScenarios).slice(0,4).map(s=>`<article><b>${esc(e49Safe(s.name))}</b><p>${esc(e46Short(e49Safe(s.setup),150))}</p><small>${esc(e46Short(e49Safe(s.task),150))}</small></article>`).join('');}
function e49ReadoutCards(sim){return arr(sim.computedReadouts).slice(0,3).map(r=>`<article><b>${esc(e49Safe(r.label))}</b><p>${esc(e46Short(e49Safe(r.meaning),160))}</p></article>`).join('');}
function e49DedupHeader(sim,C){const bridge=sim.lessonBridge||{};return `<section class="e49-dedup-head"><article><span class="chip">E49 · LAB KHÁC BIỆT THEO CHƯƠNG/BÀI</span><h3>${esc(e46Short(sim.title||'Mô phỏng',145))}</h3><p>${esc(e46Short(sim.e49UniqueObjective||sim.purpose||'',260))}</p></article><aside><b>${esc(sim.e49NoRepeatKey||'unique-lab')}</b><small>${esc(bridge.chapterTitle||sim.chapterId||'')}</small><small>Mô phỏng tổng hợp</small></aside></section>`;}
function e49DifferentiationBoard(sim){return `<section class="e49-diff-board"><article><b>Khác giữa các chương</b><p>${esc(e46Short(sim.e49ChapterContrast||'Lab này có profile riêng theo chương.',220))}</p></article><article><b>Khác trong cùng chương</b><p>${esc(e46Short(sim.e49WithinChapterDifference||'Lab này bám bài hiện tại, không dùng chung mô tả.',220))}</p></article><article><b>Dataset mini</b><p>${esc(e46Short(sim.e49MiniDataset||'Tạo dataset nhỏ, đổi một biến và đọc output.',220))}</p></article></section>`;}
function e49Experiment(sim){return `<section class="e49-experiment"><div><span class="chip">THIẾT KẾ THỬ NGHIỆM</span><h4>${esc(e46Short(sim.e49LessonLabQuestion||'Câu hỏi lab',170))}</h4></div><ol>${e49List(sim.e49ExperimentDesign,5)}</ol></section>`;}
function e49LabBoard(sim,C){const vars=arr(sim.variables).slice(0,4);return `${e49DedupHeader(sim,C)}<section class="e46-lab-board e49-lab-board"><article class="e46-model-card e49-model-card"><div><span class="chip">${esc(String(sim.simulationProfile||'LAB').toUpperCase())}</span><h3>${esc(sim.e49ChapterLabRole||'Vai trò lab')}</h3><p>${esc(e46Short(sim.purpose||'',220))}</p></div><pre>${esc((sim.liveComputationSpec&&sim.liveComputationSpec.normalizedFormula)||sim.formula||'output = f(input)')}</pre><small>${esc(sim.e49CompactConclusionPrompt||'Viết kết luận có điều kiện.')}</small></article><aside class="e46-controls e49-controls"><header><b>Biến riêng của lab này</b><button class="btn" data-act="e46-reset">Baseline</button></header>${vars.map(e46Slider).join('')}${e46PresetButtons(sim)}</aside></section>${e46ReadoutPanel(sim)}${e49DifferentiationBoard(sim)}<section class="e49-readout-grid">${e49ReadoutCards(sim)}</section>${e49Experiment(sim)}`;}
function e49Notes(sim){return `<section class="e46-notes e49-notes"><article><h4>Checklist diễn giải</h4><ul>${e49List(sim.interpretationChecklist,5)}</ul></article><article><h4>Không đọc sai</h4><ul>${e49List(sim.commonMisreadings,4)}</ul></article><article><h4>Báo cáo lab</h4><ol>${e49List(sim.reportTemplate,5)}</ol></article></section><section class="e46-report-box e49-report-box"><label><b>Kết luận lab không lặp</b><textarea class="textarea compact-textarea" data-e46-report placeholder="Ghi: Chương/Bài, biến đã đổi, output riêng, điều kiện đúng/sai, quyết định PASS/REVIEW/RISK..."></textarea></label><button class="btn" data-act="e49-fill-report">Tạo mẫu kết luận E49</button></section>`;}
function e49Flow(C){return `<footer class="e46-flow e49-flow"><div><span class="chip">FLOW MÔ PHỎNG KHÁC BIỆT</span><b>Lý thuyết → Ứng dụng → Mô phỏng tổng hợp</b><p>Không dùng lab chung chung: mỗi bài phải có biến, bối cảnh, output và lỗi đọc sai riêng.</p></div><nav><button class="btn" data-act="e46-open-theory">Xem lý thuyết</button><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>← Lab trước</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>Lab sau →</button><button class="btn green" data-act="e44-next-chapter-theory">Chương tiếp →</button></nav></footer>`;}
renderMathSimulationWorkspace=function(){const C=e46SimContext();const sim=C.active||{};const progress=C.pool.length?Math.round(((C.idx+1)/C.pool.length)*100):100;return `<div class="mathlab-shell e46-sim-shell e49-sim-shell mode-${esc(C.kind)}">${e46ModeBar(C)}<main class="panel e46-sim-main e49-sim-main"><header class="e46-head e49-topline"><div><span class="chip">E49 DEDUP LAB · MÔ PHỎNG TỔNG HỢP</span><h3>${esc(e46Short(sim.title||'Lab mô phỏng',145))}</h3></div><nav><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>←</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>→</button></nav></header><div class="e46-progress e49-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.pool.length||1}</span></div>${e49LabBoard(sim,C)}${e49Notes(sim)}${e49Flow(C)}</main></div>`;};
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]');if(!b)return;const act=b.dataset.act||'';if(act==='e49-fill-report'){e.preventDefault();e.stopPropagation();const root=b.closest('.e49-sim-shell');if(!root)return;e46UpdateReadouts(root);const txt=root.querySelector('[data-e46-report]');const score=root.querySelector('[data-e46-score]')?.textContent||'';const st=root.querySelector('[data-e46-stability]')?.textContent||'';const dec=root.querySelector('[data-e46-decision]')?.textContent||'';const title=root.querySelector('.e49-dedup-head h3')?.textContent||'Lab';if(txt)txt.value=`${title}\nBiến đã đổi: ...\nOutput riêng: Score=${score}/100, Stability=${st}/100, Decision=${dec}.\nKết luận: dùng được khi điều kiện còn đúng; nếu output nhạy với nhiễu/scale thì chuyển REVIEW/RISK và cần kiểm lại dữ liệu.`;return;}},true);
/* ===== END E49 ===== */

/* ===== E50 · Simulation Execution Board + Non-Repetition Runtime ===== */
window.__E50_SIM_EXECUTION_BOARD__ = true;
function e50List(xs,limit){xs=arr(xs).map(e49Safe).filter(Boolean);return xs.slice(0,limit||6).map(x=>`<li>${esc(e46Short(x,230))}</li>`).join('')||'<li>Chưa có dữ liệu chạy lab.</li>';}
function e50Code(xs){xs=arr(xs).map(e49Safe).filter(Boolean);return `<pre class="e50-code">${esc(xs.slice(0,7).join('\n'))}</pre>`;}
function e50Decision(rule){rule=rule||{};return `<section class="e50-decision-grid"><article><b>PASS</b><p>${esc(e46Short(rule.pass||'Kết quả ổn định và giải thích được bằng lý thuyết.',170))}</p></article><article><b>REVIEW</b><p>${esc(e46Short(rule.review||'Output nhạy, cần kiểm lại giả thiết hoặc dữ liệu.',170))}</p></article><article><b>RISK</b><p>${esc(e46Short(rule.risk||'Output trái giả thiết hoặc Failure case bị đọc nhầm là đúng.',170))}</p></article></section>`;}
function e50Visual(sim){const v=sim.e50VisualBoard||{};return `<section class="e50-visual"><div><span class="chip">BẢNG ĐỌC OUTPUT</span><h4>${esc(v.shape||'input-model-output')}</h4><p>${esc(e46Short(v.highlight||'',190))}</p></div><dl><dt>Trục X</dt><dd>${esc(v.xAxis||'input')}</dd><dt>Trục Y</dt><dd>${esc(v.yAxis||'output')}</dd><dt>Cảnh báo</dt><dd>${esc(e46Short(v.warning||'',160))}</dd></dl></section>`;}
function e50ExecutionPack(sim){return `<section class="e50-pack"><article class="mission"><span class="chip">NHIỆM VỤ LAB RIÊNG</span><h3>${esc(e46Short(sim.e50LabMission||sim.e49UniqueObjective||sim.title||'Lab',260))}</h3><p>${esc(e46Short(sim.e50RealContext||sim.purpose||'',300))}</p></article><article><b>Protocol chạy thử</b><ol>${e50List(sim.e50RunProtocol,5)}</ol></article><article><b>Xu hướng cần thấy</b><ul>${e50List(sim.e50ExpectedTrend,4)}</ul></article></section>`;}
function e50CodeLens(sim){return `<section class="e50-code-lens"><article><b>Code lens</b>${e50Code(sim.e50CodeLens)}</article><article><b>Rubric kết luận</b><ul>${e50List(sim.e50Rubric,5)}</ul></article></section>`;}
function e50DataCols(sim){const cols=arr(sim.e50MiniDataColumns).map(e49Safe).filter(Boolean).slice(0,6).map(x=>`<span>${esc(e46Short(x,42))}</span>`).join('');return `<section class="e50-data-cols"><b>Dataset/log tối thiểu</b><div>${cols||'<span>input</span><span>output</span><span>decision</span>'}</div><p>${esc(e46Short(sim.e50NextLabQuestion||'Bạn sẽ log thêm biến nào để kiểm kết luận?',210))}</p></section>`;}
function e50Board(sim,C){return `${e49DedupHeader(sim,C)}${e50ExecutionPack(sim)}<section class="e46-lab-board e49-lab-board e50-control-board"><article class="e46-model-card e49-model-card"><div><span class="chip">E50 · ${esc(String(sim.e50Profile||sim.simulationProfile||'LAB').toUpperCase())}</span><h3>Chạy, đọc, quyết định</h3><p>${esc(e46Short(sim.e50RealContext||sim.purpose||'',240))}</p></div><pre>${esc((sim.liveComputationSpec&&sim.liveComputationSpec.normalizedFormula)||sim.formula||'decision = f(input, assumptions)')}</pre></article><aside class="e46-controls e49-controls"><header><b>Biến điều khiển</b><button class="btn" data-act="e46-reset">Baseline</button></header>${arr(sim.variables).slice(0,4).map(e46Slider).join('')}${e46PresetButtons(sim)}</aside></section>${e46ReadoutPanel(sim)}${e50Visual(sim)}${e50Decision(sim.e50DecisionRule)}${e50CodeLens(sim)}${e50DataCols(sim)}`;}
renderMathSimulationWorkspace=function(){const C=e46SimContext();const sim=C.active||{};const progress=C.pool.length?Math.round(((C.idx+1)/C.pool.length)*100):100;return `<div class="mathlab-shell e46-sim-shell e49-sim-shell e50-sim-shell mode-${esc(C.kind)}">${e46ModeBar(C)}<main class="panel e46-sim-main e49-sim-main e50-sim-main"><header class="e46-head e49-topline e50-topline"><div><span class="chip">E50 EXECUTION LAB · MÔ PHỎNG TỔNG HỢP</span><h3>${esc(e46Short(sim.title||'Lab mô phỏng',145))}</h3></div><nav><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>←</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>→</button></nav></header><div class="e46-progress e49-progress e50-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.pool.length||1}</span></div>${e50Board(sim,C)}${e49Notes(sim)}${e49Flow(C)}</main></div>`;};
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]');if(!b)return;const act=b.dataset.act||'';if(act==='e50-fill-report'){e.preventDefault();e.stopPropagation();const root=b.closest('.e50-sim-shell');if(!root)return;e46UpdateReadouts(root);}},true);
/* ===== END E50 ===== */



/* ===== E51 · Simulation Evidence Board + Self-Check Notebook ===== */
window.__E51_SIM_EVIDENCE_BOARD__ = true;
function e51List(xs,limit){xs=arr(xs).map(e49Safe).filter(Boolean);return xs.slice(0,limit||6).map(x=>`<li>${esc(e46Short(x,245))}</li>`).join('')||'<li>Chưa có dữ liệu tự kiểm.</li>';}
function e51Notebook(sim){const n=sim.e51LabNotebook||{};return `<section class="e51-notebook"><article class="e51-hyp"><span class="chip">E51 · SỔ LAB TỰ KIỂM</span><h4>Giả thuyết trước khi chạy</h4><p>${esc(e46Short(n.hypothesis||sim.e50LabMission||sim.title||'',360))}</p></article><article><b>Protocol ghi vở</b><ol>${e51List(n.runPlan,5)}</ol></article><article><b>Kết quả đúng kỳ vọng</b><p>${esc(e46Short(n.expectedResult||'',260))}</p><b>Kết luận được chấp nhận</b><p>${esc(e46Short(n.acceptedConclusion||'',240))}</p></article></section>`;}
function e51Compare(sim){const rows=arr(sim.e51CompareMatrix).slice(0,4).map(r=>`<tr><td>${esc(e49Safe(r.case))}</td><td>${esc(e46Short(e49Safe(r.inputChange),110))}</td><td>${esc(e46Short(e49Safe(r.readoutExpected),120))}</td><td>${esc(e46Short(e49Safe(r.studentConclusion),130))}</td></tr>`).join('');return `<section class="e51-compare"><div><span class="chip">BẢNG SO SÁNH KẾT QUẢ</span><h4>Không chỉ chạy, phải so baseline/stress/failure</h4></div><table><thead><tr><th>Case</th><th>Input đổi gì?</th><th>Output cần thấy</th><th>Kết luận học viên</th></tr></thead><tbody>${rows}</tbody></table></section>`;}
function e51AnswerKey(sim){const n=sim.e51LabNotebook||{};return `<section class="e51-answer-grid"><article><b>Đáp án đọc lab / answer key</b><ol>${e51List(sim.e51ScenarioAnswerKey,4)}</ol></article><article><b>Dấu hiệu phải bác bỏ kết luận</b><ul>${e51List(n.rejectionSignals,4)}</ul></article><article><b>Checklist bằng chứng</b><ul>${e51List(sim.e51EvidenceChecklist,5)}</ul></article></section>`;}
function e51Defense(sim){const d=sim.e51OneMinuteDefense||{};return `<section class="e51-defense"><article><span class="chip">VẤN ĐÁP LAB 60 GIÂY</span><h4>Nói được kết luận, không chỉ bấm slider</h4><p>${esc(e46Short(d.vi||sim.e51NotebookPrompt||'',360))}</p></article><article><b>Русский шаблон</b><p>${esc(e46Short(d.ru||'Опишите параметр, результат и условие применимости модели.',330))}</p></article></section>`;}
function e51ReportBox(sim){return `<section class="e51-report"><label><b>Kết luận lab của tôi</b><textarea class="textarea compact-textarea" data-e51-report placeholder="${esc(sim.e51NotebookPrompt||'Ghi giả thuyết, biến đã đổi, output và quyết định PASS/REVIEW/RISK...')}"></textarea></label><button class="btn gold" data-act="e51-fill-notebook">Tạo mẫu kết luận E51</button></section>`;}
function e51Board(sim,C){return `${e50Board(sim,C)}${e51Notebook(sim)}${e51Compare(sim)}${e51AnswerKey(sim)}${e51Defense(sim)}${e51ReportBox(sim)}`;}
renderMathSimulationWorkspace=function(){const C=e46SimContext();const sim=C.active||{};const progress=C.pool.length?Math.round(((C.idx+1)/C.pool.length)*100):100;return `<div class="mathlab-shell e46-sim-shell e49-sim-shell e50-sim-shell e51-sim-shell mode-${esc(C.kind)}">${e46ModeBar(C)}<main class="panel e46-sim-main e49-sim-main e50-sim-main e51-sim-main"><header class="e46-head e49-topline e50-topline e51-topline"><div><span class="chip">E51 EVIDENCE LAB · MÔ PHỎNG TỔNG HỢP</span><h3>${esc(e46Short(sim.title||'Lab mô phỏng',145))}</h3><p>Chạy mô phỏng → đọc output → tự kiểm bằng answer key → viết kết luận có điều kiện.</p></div><nav><button class="btn" data-act="e46-sim-prev" ${C.idx<=0?'disabled':''}>←</button><button class="btn primary" data-act="e46-sim-next" ${C.idx>=Math.max(0,C.pool.length-1)?'disabled':''}>→</button></nav></header><div class="e46-progress e49-progress e50-progress e51-progress"><i style="width:${progress}%"></i><span>${C.idx+1}/${C.pool.length||1}</span></div>${e51Board(sim,C)}${e49Notes(sim)}${e49Flow(C)}</main></div>`;};
document.addEventListener('click',function(e){const b=e.target.closest('button,[data-act]');if(!b)return;const act=b.dataset.act||'';if(act==='e51-fill-notebook'){e.preventDefault();e.stopPropagation();const root=b.closest('.e51-sim-shell');if(!root)return;try{e46UpdateReadouts(root);}catch(_){} const txt=root.querySelector('[data-e51-report]');const score=root.querySelector('[data-e46-score]')?.textContent||'...';const st=root.querySelector('[data-e46-stability]')?.textContent||'...';const conf=root.querySelector('[data-e46-confidence]')?.textContent||'...';const dec=root.querySelector('[data-e46-decision]')?.textContent||'...';const title=root.querySelector('.e51-topline h3')?.textContent||'Lab';if(txt)txt.value=`${title}\nGiả thuyết: ...\nBiến đã đổi: ...\nOutput đọc được: Score=${score}/100, Stability=${st}/100, Confidence=${conf}/100, Decision=${dec}.\nTự kiểm: so với baseline/stress/failure và answer key.\nKết luận: PASS/REVIEW/RISK vì ...; chỉ dùng khi điều kiện ... còn đúng.`;return;}},true);
