/* ===== START E52 · THEORY STRUCTURE DEDUP + DIRECT READER ===== */
window.__E52_THEORY_STRUCTURE_DEDUP__ = true;
function e52Plain(x){return str(x||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e52EscapeReg(s){return String(s||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function e52ChapterNoFrom(item){
 const raw=e52Plain([item&&item.chapterNo,item&&item.chapterId,item&&item.id,item&&item.lessonId,item&&item.chapterTitle,item&&item.title].filter(Boolean).join(' '));
 const m=raw.match(/Chương\s*([0-9]+)/i)||raw.match(/C(\d{2})(?:\D|$)/i)||raw.match(/§\s*([0-9]+)\./);
 return m?String(Number(m[1])):'';
}
function e52StripChapterPrefix(title,no){
 let s=e52Plain(title||'');
 const n=String(no||e52ChapterNoFrom({chapterTitle:s})||'').replace(/^0+/,'');
 if(n){
  const re=new RegExp('^(?:Chương|CHƯƠNG)\\s*0*'+e52EscapeReg(n)+'\\s*[·:\\-–—]?\\s*','i');
  s=s.replace(re,'').trim();
 }
 s=s.replace(/^(?:Chương|CHƯƠNG)\s*[0-9]+\s*[·:\-–—]?\s*/i,'').trim();
 return s||'Nội dung chương';
}
function e52ChapterLabel(item){const no=e52ChapterNoFrom(item)||''; const title=e52StripChapterPrefix(item&&item.chapterTitle||'',no); return no?`Chương ${no} · ${title}`:title;}
function e52SectionNoFrom(item){
 const raw=e52Plain([item&&item.displayTitle,item&&item.title,item&&item.id,item&&item.lessonId].filter(Boolean).join(' '));
 let m=raw.match(/§\s*([0-9]+(?:\.[0-9]+)?)/)||raw.match(/(?:^|\D)([0-9]+\.[0-9]+)\s*[\.·:\-–—]?/)||raw.match(/C(\d{2}).*?L(\d{2})/i);
 if(m){ if(m.length>2)return String(Number(m[1]))+'.'+String(Number(m[2])); return m[1].replace(/^0+/,''); }
 return '';
}
function e52CleanLessonTitle(item){
 let s=e52Plain((item&&typeof item==='object')?(item.displayTitle||item.title||item.shortTitle||item.name):(item||''));
 s=s.replace(/^§\s*[0-9]+(?:\.[0-9]+)?\s*[\.·:\-–—]?\s*/,'');
 s=s.replace(/^\$?\s*[0-9]+(?:\.[0-9]+)?\s*[\.·:\-–—]?\s*/,'');
 s=s.replace(/^L\s*0*\d+\s*[\.·:\-–—]?\s*/i,'');
 return s.trim()||'Nội dung bài học';
}
function e52LessonDisplay(item){const sec=e52SectionNoFrom(item); const title=e52CleanLessonTitle(item); return sec?`§${sec} · ${title}`:title;}
function e52CleanSlideTitle(title,lesson){
 let s=e52Plain(title||''); const lt=e52CleanLessonTitle(lesson||{});
 if(lt && s.toLowerCase().startsWith(lt.toLowerCase())) s=s.slice(lt.length).replace(/^\s*[·:\-–—]\s*/,'').trim();
 s=s.replace(/^§\s*[0-9]+(?:\.[0-9]+)?\s*[\.·:\-–—]?\s*/,'').trim();
 return s||'Nội dung';
}
function e52IsFinalSlide(slide,lesson,idx,total){
 const t=e52Plain(slide&&slide.title).toLowerCase();
 return !!(slide&&slide.finalSummaryOnly)||idx===Math.max(0,(total||0)-1)||/tổng\s*kết|tong\s*ket|summary/.test(t);
}
const E52_PREV_V33_META=v33ResourceMeta;
v33ResourceMeta=function(item){
 const meta=E52_PREV_V33_META(item||{}); const no=meta.chapterNo||e52ChapterNoFrom(Object.assign({},item||{},meta));
 return Object.assign({},meta,{chapterNo:no,chapterTitle:e52StripChapterPrefix(meta.chapterTitle,no)});
};
const E52_PREV_V37_RECORDS=v37RecordsForMode;
v37RecordsForMode=function(mode){
 const pack=E52_PREV_V37_RECORDS(mode);
 if(mode==='theory'){
  return Object.assign({},pack,{
   title:x=>e52CleanLessonTitle(x),
   sub:x=>e52ChapterLabel(x),
   number:x=>e52SectionNoFrom(x)||'§'
  });
 }
 return pack;
};
