 const active=xs[state.exerciseIndex]||xs[0]||null;
 const levelButtons=['all'].concat(e53ExerciseLevels()).map(l=>{const count=l==='all'?all.length:all.filter(x=>e53ExerciseLevelKey(x)===l).length;return `<button class="e53-level-pill ${selected===l?'active':''}" data-exercise-level-set="${esc(l)}"><b>${esc(l==='all'?'Tất cả':e53ExerciseLevelLabel(l))}</b><span>${count}</span></button>`;}).join('');
 const nextLesson=e36FirstLessonOfNextChapter(ctx.lesson||ctx.id,1);
 const prevDisabled=!active||state.exerciseIndex<=0, nextDisabled=!active||state.exerciseIndex>=xs.length-1;
