 const progress=xs.length?Math.round(((state.exerciseIndex+1)/xs.length)*100):0;
 const level=e53ExerciseLevelKey(active||{});
 const body=active?`<article class="e53-ex-card" tabindex="0">
  <header><div><span class="chip">${esc(e53ExerciseLevelLabel(level))}</span><h3>${esc(title)}</h3><p>${esc(e53Short(active.learningGoal||active.mode||'Luyện đúng theo bài lý thuyết hiện tại.',180))}</p></div><b>${state.exerciseIndex+1}/${xs.length}</b></header>
  <div class="e53-progress"><i style="width:${progress}%"></i><span>${progress}%</span></div>
  <section class="e53-task-grid"><article><h4>Dữ kiện</h4><ul>${arr(active.given).map(x=>`<li>${esc(e53Short(x,180))}</li>`).join('')||'<li>Dùng đúng bài lý thuyết hiện tại.</li>'}</ul></article><article><h4>Yêu cầu</h4><ol>${e53ExercisePrompt(active)}</ol></article></section>
  <details class="e53-answer"><summary>Xem đáp án mẫu và rubric sau khi tự làm</summary><div class="e53-answer-grid"><article><h4>Đáp án mẫu</h4><ol>${e53ExerciseAnswer(active)}</ol></article><article><h4>Rubric</h4><ul>${e53ExerciseRubric(active)}</ul></article><article><h4>Lỗi dễ mắc</h4><ul>${e53ExerciseMistakes(active)}</ul></article></div></details>
 </article>`:`<div class="note e53-empty">Bài này chưa có bài tập đúng mức đang chọn. Hãy chọn mức khác hoặc quay lại lý thuyết.</div>`;
 return `<section class="panel e53-ex-shell">
  <header class="e53-ex-head"><div><span class="chip">📝 BÀI TẬP · vào thẳng nội dung</span><h3>${esc(ctx.title||'Bài học hiện tại')}</h3><p>Đủ 4 mức Dễ · Trung bình · Nâng cao · Khó. Mỗi mức có nhiệm vụ khác nhau, không copy lặp.</p></div><nav><button class="btn" data-learn="theory">Xem lại lý thuyết</button><button class="btn" data-act="prev-exercise" ${prevDisabled?'disabled':''}>← Bài trước</button><button class="btn primary" data-act="next-exercise" ${nextDisabled?'disabled':''}>Bài sau →</button><button class="btn green" data-act="exercise-next-chapter-theory" ${nextLesson?'':'disabled'}>Chương tiếp →</button></nav></header>
  <nav class="e53-levels">${levelButtons}</nav>${body}
 </section>`;
