 if(detailed.length)return detailed.map(x=>({question:e53Text(x.question||x.q||x),shortAnswer:e53Text(x.shortAnswer||x.answer||x.a||''),fullAnswer:e53Text(x.fullAnswer||x.answer||x.a||x.shortAnswer||''),criteria:arr(x.correctnessCriteria),wrong:e53Text(x.commonWrongAnswer||''),score:e53Text(x.scoreGuide||'')}));
 return arr(active&&active.professorQuestions).map(q=>({question:e53Text(q),shortAnswer:e53Text(active&&active.modelAnswer||''),fullAnswer:e53Text(active&&active.modelAnswer||''),criteria:[],wrong:'',score:''}));
