window.__E54_SIM_FORMULA_DEEP_REBUILD__ = true;
function e54Text(v){try{return v39TextFromAny?v39TextFromAny(v):String(v??'');}catch(_){return String(v??'');}}
function e54Short(v,n=180){v=e54Text(v).replace(/\s+/g,' ').trim();return v.length>n?v.slice(0,n-1)+'…':v;}
function e54List(xs,limit=5){xs=arr(xs).map(e54Text).filter(Boolean);return xs.slice(0,limit).map(x=>`<li>${esc(e54Short(x,210))}</li>`).join('')||'<li>Chưa có dữ liệu.</li>';}
function e54FormulaInfo(item){const base=Object.assign({},v34FormulaInfo(item||{}));return Object.assign(base,{formula:item?.formula||item?.rule||base.formula||'',title:e52CleanLessonTitle(item||{})||base.title||item?.title||'Công thức'});}
function e54CurrentFormulaIndex(list,key){const k=key==='grammar'?'grammarIndex':'vocabIndex';state[k]=Math.min(Math.max(0,Number(state[k])||0),Math.max(0,list.length-1));return state[k];}
function e54PartRows(parts){parts=arr(parts).slice(0,5);return parts.map(p=>`<tr><td><code>${esc(e54Text(p.symbol||p.name||'x'))}</code></td><td>${esc(e54Short(p.function||p.meaning||p.role||'',190))}</td></tr>`).join('')||'<tr><td><code>x</code></td><td>Dữ liệu đầu vào cần kiểm điều kiện trước khi tính.</td></tr>';}
function e54FormulaBack(item,info){const back=item.cardBackDeepAnalysis||{};const parts=arr(back.parts||item.formulaParts||item.symbolFunctionTable);return `<div class="e54-flip-back"><span class="chip">PHÂN TÍCH SÂU CÔNG THỨC</span><h3>${esc(e54Short(back.role||item.functionMeaning||info.meaning,220))}</h3><p>${esc(e54Short(back.inputOutput||'Input → kiểm điều kiện → công thức → output → kết luận.',220))}</p><table class="e54-symbol-table"><tbody>${e54PartRows(parts)}</tbody></table><ul>${e54List(back.effectOfChangingParts||item.deepSensitivityChecklist||[],3)}</ul></div>`;}
renderVocab=function(){
 try{
  const list=getVocab(); if(!list.length)return `<section class="panel vocab-empty learning-recovery-card"><span class="chip">🧮 Công thức</span><h3>Chưa có công thức phù hợp</h3></section>`;
  const idx=e54CurrentFormulaIndex(list,'vocab'); const item=list[idx]||list[0]||{}; const info=e54FormulaInfo(item); const flipped=!!state.vocabFlipped; const meta=v33ResourceMeta(item);
  const back=e54FormulaBack(item,info);
  const front=`<div class="e54-flip-front"><span class="chip">CÔNG THỨC TRỌNG TÂM</span><div class="term term-xlong formula-flash-term">${esc(info.formula||info.title)}</div><p>${esc(e54Short(item.quickUse||item.whenToUse||'Dùng khi đã xác định input, điều kiện áp dụng và output cần đọc.',170))}</p><div class="v1310-pron">↺ Lật thẻ để phân tích sâu công thức</div></div>`;
  const cond=e54List(item.conditions||item.deepAssumptionGates,4), mis=e54List(item.commonMistakes||item.deepFailureModes,4);
  return `<div class="vocab-studio formula-v35-shell e54-formula-shell">
   <section class="panel formula-v35-topbar e54-formula-topbar"><div><span class="chip">🧮 CÔNG THỨC · ${esc(stageTitle(meta.stage||state.stage))}</span><h3>${esc(e54Short(info.title,120))}</h3><p>${esc(v35FormulaChapterLabel(item))}</p></div><div class="formula-v35-top-actions e36-formula-actions"><input class="input" data-input="vocabQuery" value="${esc(state.vocabQuery||'')}" placeholder="Tìm công thức, chương, khái niệm...">${e36FormulaNav('vocab')}<button class="btn primary formula-v35-picker-btn" data-act="open-formula-picker">☷ Chọn chương</button></div></section>
   <main class="panel vocab-card-panel e54-formula-main"><header class="e54-formula-head"><div><span class="chip">${esc(item.lessonId||item.chapterId||'FORMULA')}</span><h3>${esc(e54Short(info.title,140))}</h3></div><b>${idx+1}/${list.length}</b></header>
    <button class="flash visual-flash e54-flash ${flipped?'flipped':''}" data-act="toggle-vocab-flip"><div class="flash-inner">${flipped?back:front}</div></button>
    <div class="vocab-actions"><button class="btn" data-act="prev-vocab">← Mục trước</button><button class="btn primary" data-act="toggle-vocab-flip">${flipped?'Quay lại công thức':'Lật thẻ để phân tích sâu công thức'}</button><button class="btn" data-act="next-vocab">Mục sau →</button></div>
    <section class="e54-formula-detail"><article><b>Chức năng ký hiệu</b><p>${esc(item.meaningPanelRole||'Bảng này giải thích vai trò từng ký hiệu, không lặp mặt sau thẻ.')}</p><table class="e54-symbol-table"><tbody>${e54PartRows(item.symbolFunctionTable||item.formulaParts)}</tbody></table></article><article><b>Điều kiện áp dụng</b><ul>${cond}</ul></article><article><b>Lỗi cần tránh</b><ul>${mis}</ul></article></section>
   </main>
  </div>`;
 }catch(e){console.error('FORMULA_RENDER_GUARD_E54',e);return `<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI CÔNG THỨC</span><h3>Không render được tab Công thức</h3><p>${esc(e?.message||e)}</p></section>`;}
};
function e54DeepInfo(item){const info=e48DeepInfo?e48DeepInfo(item):e54FormulaInfo(item);return Object.assign({},info,{deepSystemRole:item.deepSystemRole||info.deepRoleStatement||'Kiểm công thức như một mô-đun trong hệ thống.',deepImplementationAudit:arr(item.deepImplementationAudit),deepFailureModes:arr(item.deepFailureModes||info.deepFailureModes),deepAssumptionGates:arr(item.deepAssumptionGates||info.deepAssumptionGates),deepMiniExperiment:item.deepMiniExperiment||info.deepMiniExperiment||{}});}
function e54DeepMini(exp){if(!exp||typeof exp!=='object')return '<p>Chạy mô phỏng tương ứng, đổi một biến và ghi điều kiện làm kết luận sai.</p>';return `<p>${esc(e54Short(exp.goal||'Kiểm công thức bằng mô phỏng nhỏ.',180))}</p><ol>${e54List(exp.steps||[],4)}</ol><b>${esc(e54Short(exp.passRule||'PASS khi giả thiết còn đúng và output ổn định.',160))}</b>`;}
renderGrammar=function(){
 try{
  const xs=grammarDeepItems(); if(!xs.length)return `<section class="panel learning-recovery-card"><span class="chip">∑ Công thức sâu</span><h3>Chưa có dữ liệu công thức sâu</h3></section>`;
  const idx=e54CurrentFormulaIndex(xs,'grammar'); const g=xs[idx]||xs[0]||{}; const info=e54DeepInfo(g); const related=arr(g.conceptIds).slice(0,8).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>concept</span>';
  return `<div class="grammar-luxe-shell e54-deep-shell">
   <section class="panel e54-deep-top"><div><span class="chip">∑ CÔNG THỨC SÂU · AUDIT HỆ THỐNG</span><h3>${esc(e54Short(info.title||g.title||'Công thức sâu',140))}</h3><p>Tab này không nhắc lại thẻ công thức. Nó kiểm xem công thức có được phép dùng trong hệ thống thật, code, mô phỏng và báo cáo hay không.</p></div><div class="formula-v35-top-actions e36-formula-actions"><input class="input" data-input="grammarQuery" value="${esc(state.grammarQuery||'')}" placeholder="Tìm giả thiết, lỗi triển khai, độ nhạy...">${e36FormulaNav('grammar')}<button class="btn primary formula-v35-picker-btn" data-act="open-grammar-picker">☷ Chọn chương</button></div></section>
   <main class="panel e54-deep-main"><header class="e54-deep-head"><div><span class="chip">${esc(g.lessonId||g.chapterId||'DEEP')}</span><h3>Audit công thức trong pipeline</h3><p>${esc(e54Short(info.deepSystemRole||info.deepFormulaTakeaway,260))}</p></div><b>${idx+1}/${xs.length}</b></header>
    <section class="e54-deep-formula"><b>Công thức đang audit</b><pre>${esc(info.formula||g.rule||'')}</pre></section>
    <section class="e54-deep-grid"><article class="gate"><b>1 · Cổng giả thiết</b><ul>${e54List(info.deepAssumptionGates,5)}</ul></article><article><b>2 · Đưa vào code/pipeline</b><ol>${e54List(info.deepImplementationAudit||info.deepSystemPipeline,5)}</ol></article><article><b>3 · Mini lab kiểm công thức</b>${e54DeepMini(info.deepMiniExperiment)}</article><article class="risk"><b>4 · Khi nào công thức hỏng</b><ul>${e54List(info.deepFailureModes,5)}</ul></article></section>
    <section class="e54-deep-defense"><article><b>Câu hỏi debug/vấn đáp</b><ol>${e54List(info.deepDebugQuestions||info.deepDefensePoints,5)}</ol></article><article><b>Concept liên quan</b><div class="formula-concept-tags">${related}</div></article></section>
    <footer class="e54-deep-footer"><div><span class="chip">ĐỌC SÂU → CHẠY MÔ PHỎNG → KẾT LUẬN</span><b>Đủ điều kiện mới được dùng công thức</b><p>Nếu giả thiết hoặc output không ổn, chuyển REVIEW/RISK thay vì kết luận chắc chắn.</p></div><nav><button class="btn" data-view="vocab">Xem thẻ công thức</button><button class="btn" data-learn="theory">Xem lý thuyết</button><button class="btn gold" data-act="e37-open-sim-theory">Mô phỏng kiểm công thức</button><button class="btn green" data-act="exercise-next-chapter-theory">Chương tiếp →</button></nav></footer>
   </main>
  </div>`;
 }catch(e){console.error('GRAMMAR_RENDER_GUARD_E54',e);return `<section class="panel learning-recovery-card"><span class="chip danger-chip">LỖI CÔNG THỨC SÂU</span><h3>Không render được tab Công thức sâu</h3><p>${esc(e?.message||e)}</p></section>`;}
};
function e54SimContext(){return e46SimContext?e46SimContext():{pool:arr(DB.simulations),active:arr(DB.simulations)[0]||{},idx:0,kind:'unified'};}
function e54VarValue(v,i){let d=Number(v.default);if(!isFinite(d))d=0.3+i*0.13;return Math.max(0,Math.min(1,d));}
function e54VisualSvg(sim){const type=sim.visualType||sim.e54VisualModel?.type||'vector_plane';const data=sim.e54VisualModel?.dataset||{};let svg='';
 if(type==='vector_plane'||type==='scatter_projection') svg=`<svg viewBox="0 0 360 220"><defs><linearGradient id="g54" x1="0" x2="1"><stop offset="0" stop-color="#38bdf8"/><stop offset="1" stop-color="#22c55e"/></linearGradient></defs><line x1="30" y1="110" x2="330" y2="110"/><line x1="180" y1="20" x2="180" y2="200"/><g data-e54-cloud>${arr(data.points).slice(0,8).map((p,i)=>`<circle cx="${180+(Number(p.x)||0)*90}" cy="${110-(Number(p.y)||0)*70}" r="6"/><text x="${188+(Number(p.x)||0)*90}" y="${106-(Number(p.y)||0)*70}">${esc(p.label||i+1)}</text>`).join('')}</g><path data-e54-path d="M180 110 L275 58"/><path class="alt" d="M180 110 L245 145"/></svg>`;
 else if(type==='distribution_bars') svg=`<svg viewBox="0 0 360 220"><line x1="35" y1="190" x2="330" y2="190"/>${arr(data.probabilities).slice(0,6).map((p,i)=>`<rect x="${55+i*46}" y="${190-(Number(p)||.1)*420}" width="30" height="${(Number(p)||.1)*420}"/><text x="${60+i*46}" y="205">${esc((data.classes||[])[i]||i+1)}</text>`).join('')}</svg>`;
 else if(type==='time_series_line'||type==='spectrum_filter') {const series=arr(data.series).length?arr(data.series):[.2,.4,.3,.7,.5,.8,.6,.9];const pts=series.map((y,i)=>`${30+i*(300/(series.length-1))},${140-Number(y)*45}`).join(' ');svg=`<svg viewBox="0 0 360 220"><line x1="30" y1="170" x2="335" y2="170"/><polyline points="${pts}"/><path data-e54-filter d="M30 135 C90 70 150 190 210 125 S300 95 335 140"/></svg>`;}
 else if(type==='loss_landscape') svg=`<svg viewBox="0 0 360 220"><path d="M35 190 C70 80 110 50 160 115 S260 210 325 45"/><circle data-e54-dot cx="85" cy="96" r="8"/><circle cx="315" cy="48" r="5"/><text x="250" y="35">min?</text></svg>`;
 else if(type==='state_space') svg=`<svg viewBox="0 0 360 220"><rect x="45" y="70" width="75" height="55" rx="14"/><rect x="145" y="70" width="75" height="55" rx="14"/><rect x="245" y="70" width="75" height="55" rx="14"/><path d="M120 98 L145 98 M220 98 L245 98 M180 125 C180 170 80 170 80 126"/><circle data-e54-dot cx="180" cy="98" r="7"/></svg>`;
 else svg=`<svg viewBox="0 0 360 220"><rect x="40" y="40" width="280" height="140" rx="18"/><line x1="40" y1="80" x2="320" y2="80"/><line x1="130" y1="40" x2="130" y2="180"/><line x1="230" y1="40" x2="230" y2="180"/><circle data-e54-dot cx="130" cy="110" r="8"/><text x="62" y="67">Baseline</text><text x="156" y="67">Stress</text><text x="250" y="67">Risk</text></svg>`;
 return `<div class="e54-visual-canvas" data-e54-visual="${esc(type)}">${svg}</div>`;}
function e54Controls(sim){const vars=arr(sim.variables).slice(0,4);return `<aside class="e54-sim-controls"><header><b>Biến điều khiển thật</b><button class="btn" data-act="e54-reset">Baseline</button></header>${vars.map((v,i)=>`<label><span>${esc(v.label||v.name||('Biến '+(i+1)))}</span><input type="range" min="0" max="1" step="0.01" value="${e54VarValue(v,i)}" data-e54-range="${esc(v.name||('v'+i))}"><output data-e54-val="${esc(v.name||('v'+i))}">${e54VarValue(v,i).toFixed(2)}</output><small>${esc(e54Short(v.effect||'',120))}</small></label>`).join('')}</aside>`;}
function e54Readouts(){return `<section class="e54-readouts"><article><b>Score</b><span data-e54-score>72</span></article><article><b>Stability</b><span data-e54-stability>68</span></article><article><b>Confidence</b><span data-e54-confidence>74</span></article><article class="decision"><b>Decision</b><span data-e54-decision>REVIEW</span></article></section>`;}
function e54SimulationBoard(sim,C){const vm=sim.e54VisualModel||{};return `<section class="e54-sim-board"><div class="e54-sim-visual"><header><span class="chip">VISUAL LAB · ${esc(vm.type||sim.visualType||'board')}</span><h3>${esc(e54Short(vm.visualQuestion||sim.title||'Quan sát output đổi theo biến',150))}</h3></header>${e54VisualSvg(sim)}${e54Readouts()}</div>${e54Controls(sim)}</section>`;}
function e54SimProtocol(sim){return `<section class="e54-sim-protocol"><article><h4>Chạy gì?</h4><ol>${e54List(sim.e54RunProtocol||sim.explorationSteps,5)}</ol></article><article><h4>Đọc gì?</h4><ul>${e54List(arr(sim.e54OutputReadouts).map(x=>x.meaning||x.label)||sim.expectedOutputs,4)}</ul></article><article><h4>Kết luận</h4><p>${esc(e54Short(sim.e54ConclusionTemplate||'Ghi biến mạnh nhất, output đổi gì và điều kiện kết luận.',260))}</p></article></section>`;}
