function e54Compute(root){const vals=[];root.querySelectorAll('[data-e54-range]').forEach(r=>{const v=Number(r.value)||0;vals.push(v);const out=root.querySelector(`[data-e54-val="${CSS.escape(r.dataset.e54Range)}"]`);if(out)out.textContent=v.toFixed(2);});const avg=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:.5;const spread=vals.length?Math.max(...vals)-Math.min(...vals):.2;const score=Math.max(0,Math.min(100,Math.round(55+avg*45-spread*18)));const stability=Math.max(0,Math.min(100,Math.round(88-spread*55)));const conf=Math.max(0,Math.min(100,Math.round((score+stability)/2)));const decision=score>78&&stability>62?'PASS':score<48||stability<42?'RISK':'REVIEW';const set=(q,v)=>{const el=root.querySelector(q);if(el)el.textContent=v;};set('[data-e54-score]',score);set('[data-e54-stability]',stability);set('[data-e54-confidence]',conf);set('[data-e54-decision]',decision);const dot=root.querySelector('[data-e54-dot]');if(dot){dot.setAttribute('cx',String(50+avg*250));dot.setAttribute('cy',String(180-spread*120));}root.querySelectorAll('[data-e54-cloud] circle').forEach((c,i)=>{c.setAttribute('r',String(4+Math.abs((vals[i%vals.length]||.5)-.5)*10));});const p=root.querySelector('[data-e54-path]');if(p)p.setAttribute('d',`M180 110 L${180+avg*130} ${110-spread*120}`);return {score,stability,conf,decision};}
