function e64CompactDom(){
  try{
    document.body.classList.add('e64-layout-polish');
    // Clean visible text labels after render, without touching input values.
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){
      const p=n.parentElement; if(!p||['SCRIPT','STYLE','TEXTAREA','INPUT'].includes(p.tagName))return NodeFilter.FILTER_REJECT;
      return /Chương\s*\d+|§\s*\d|Mô phỏng\s+lý thuyết|Mô phỏng\s+ứng dụng|THEORY\s*LAB|CASE\s*LAB/.test(n.nodeValue||'')?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;
    }});
    let node; while((node=walker.nextNode())) node.nodeValue=e64CleanText(node.nodeValue);
    // In each compact tool bar, keep only one "Chọn chương" action so the same function is not shown twice.
    document.querySelectorAll('.v39-picker-tools,.v38-picker-side,.formula-v35-top-actions,.e47-formula-tools,.e48-deep-tools,.e36-sim-navline').forEach(group=>{
      const buttons=[...group.querySelectorAll('button')].filter(b=>/Chọn\s+chương/i.test(b.textContent||''));
      buttons.forEach((b,i)=>{ if(i<buttons.length-1) b.classList.add('e64-duplicate-picker-hidden'); });
    });
    // Unified simulation panel: if older UI outputs multiple mode cards, visually keep one unified entry.
    document.querySelectorAll('.v39-sim-mode-panel').forEach(panel=>{
      const cards=[...panel.querySelectorAll('.v39-sim-mode')];
      if(cards.length>1){ cards.slice(1).forEach(c=>c.classList.add('e64-duplicate-picker-hidden')); }
      panel.querySelectorAll('h3,b,small,p,span').forEach(el=>{el.textContent=e64CleanText(el.textContent||'');});
    });
    document.querySelectorAll('h1,h2,h3,h4,.v39-picker-copy,.formula-v35-topbar,.e48-deep-top,.e54-deep-top').forEach(el=>el.classList.add('e64-compact-title'));
  }catch(err){ console.warn('E64 compact DOM skipped',err); }
}
