function e78Key(x){return str(x&& (x.lessonId||x.id||x.title||x.question) || '');}
function e78Text(x){return String(x==null?'':x).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function e78Clip(x,n){return clip?clip(e78Text(x),n||120):e78Text(x).slice(0,n||120);}
