function e79UpdateSim(root){
  root=root?.closest?root.closest('.e79-sim-shell'):root; if(!root)return;
  const ranges=[...root.querySelectorAll('[data-e79-range]')]; if(!ranges.length)return;
  const vals=ranges.map((r,i)=>{const min=e79Num(r.min,0),max=e79Num(r.max,1),v=e79Num(r.value,min); const pct=max===min?0:(v-min)/(max-min); const card=r.closest('.e79-control-card'); if(card){const out=card.querySelector('output'); if(out)out.textContent=String(Number(v.toFixed?v.toFixed(2):v)); const fill=card.querySelector('.e79-range-shell i'); if(fill)fill.style.width=(Math.max(0,Math.min(1,pct))*100)+'%';} return Math.max(0,Math.min(1,pct));});
  const avg=vals.reduce((a,b)=>a+b,0)/vals.length; const spread=Math.max(...vals)-Math.min(...vals); const score=Math.round(Math.max(0,Math.min(100,50+avg*45-spread*22))); const stability=Math.round(Math.max(0,Math.min(100,88-spread*58))); const confidence=Math.round((score+stability)/2); const decision=score>78&&stability>60?'PASS':(score<45||stability<40?'RISK':'REVIEW');
  const values=[score,stability,confidence,decision]; values.forEach((v,i)=>{const el=root.querySelector(`[data-e79-out="${i}"]`); if(el)el.textContent=String(v);});
  const dot=root.querySelector('[data-e79-dot]'); if(dot){dot.setAttribute('cx',String(70+avg*360)); dot.setAttribute('cy',String(195-spread*110-avg*42));}
  root.querySelectorAll('[data-e79-bar]').forEach((b,i)=>{const h=Math.max(42,Math.min(150,(vals[i%vals.length]||.35)*135+35)); b.setAttribute('y',String(210-h)); b.setAttribute('height',String(h));});
  const line=root.querySelector('[data-e79-line]'); if(line){line.setAttribute('points',`70,${190-avg*55} 150,${165-vals[0]*80} 230,${180-vals[1%vals.length]*90} 310,${150-vals[2%vals.length]*88} 420,${160-spread*80}`);}
}
