  if(/đạo hàm|gradient|tối ưu|lagrange|kkt|mpc/.test(t))return {icon:'∇',name:'Gradient & tối ưu',mission:'đổi bước học/ràng buộc để thấy hội tụ hoặc lệch nghiệm',visual:'loss'};
  if(/xác suất|bayes|thống kê|pca|hiệp phương sai|tương quan/.test(t))return {icon:'🎲',name:'Xác suất · thống kê',mission:'đọc phân phối, độ tin cậy, tương quan và sai số suy luận',visual:'bars'};
