function e81VarCards(sim){return arr(sim.variables).slice(0,5).map((v,i)=>{const min=Number(v.min??0),max=Number(v.max??1),def=Number(v.default??v.value??(min+(max-min)*(0.3+i*.12))),step=Number(v.step??0.01);const pct=max===min?0:Math.max(0,Math.min(100,((def-min)/(max-min))*100));return `<article class="e81-var"><label><b>${esc(v.label||v.name||('Biến '+(i+1)))}</b><output>${esc(Number.isFinite(def)?Number(def.toFixed?def.toFixed(2):def):def)}</output></label><div class="e81-range"><i style="width:${pct}%"></i><input type="range" data-e81-range min="${esc(min)}" max="${esc(max)}" step="${esc(step)}" value="${esc(def)}"></div><small>${esc(e81Short(v.role||v.effect||v.meaning||'Biến này tác động trực tiếp tới output mô phỏng.',150))}</small></article>`;}).join('')||'<article class="e81-var"><b>Không có biến</b><small>Kiểm data/simulations.json.</small></article>';}
