  try{const lessons=e81Lessons(); const old=state.lessonId; state.lessonId=e81LessonKey(lessons[0]||{}); state.simulationTargetId=state.lessonId; simA=String(renderMathSimulationWorkspace()||''); const other=lessons.find(x=>str(x.chapterId)!==str((lessons[0]||{}).chapterId))||lessons[1]||lessons[0]; state.lessonId=e81LessonKey(other||{}); state.simulationTargetId=state.lessonId; simB=String(renderMathSimulationWorkspace()||''); state.lessonId=old; state.simulationTargetId=old; }catch(e){ok=false;err+=' sim:'+String(e&&e.message||e);}
