  const selects=Array.from(document.querySelectorAll('.e84-map-select'));
  const pairs=[]; const targetSeen={}; const dup=[];
  selects.forEach(sel=>{const idx=Number(sel.dataset.e84Index||0); const target=str(sel.value||''); const row=pending.analysis.rows[idx]; if(!row)return; if(target){ if(targetSeen[target])dup.push(target); targetSeen[target]=1; pairs.push({row,target}); }});
  if(dup.length){toast('Không tích hợp: trùng bài đích '+dup.slice(0,4).join(', '));return false;}
  if(!pairs.length){toast('Chưa map bài nào. Hãy chọn bài đích trước.');return false;}
  const current=arr(DB.simulations).slice(); const map=new Map(current.map(s=>[str(s.lessonId||s.id),s])); let replaced=0,inserted=0,skipped=pending.analysis.rows.length-pairs.length,first=''; const details=[];
  try{
    pairs.forEach(p=>{const old=map.get(p.target); const next=e84MappedRuntimeSimulation(p.row.mini,p.target,pending.pack,old); if(old)replaced++; else inserted++; map.set(p.target,next); if(!first)first=p.target; details.push({sourceId:p.row.sourceId,targetLessonId:p.target,replaced:!!old,title:next.title});});
  }catch(err){toast('Không tích hợp: '+String(err&&err.message||err));return false;}
  const ordered=current.map(s=>map.get(str(s.lessonId||s.id))).filter(Boolean); const used=new Set(ordered.map(s=>str(s.lessonId||s.id))); map.forEach((s,k)=>{if(!used.has(k))ordered.push(s);});
  DB.simulations=ordered.filter(s=>s&&s.lessonId&&e84LessonById(s.lessonId));
  USER_DATA_SOURCES.add('simulations'); saveDB();
  state.storageGroup=E83_STORAGE_SIM_GROUP; state.storageFile='simulations'; state.storagePreviewLimit=20; state.view='storage'; state.simulationKind='unified';
  if(first){state.lessonId=first; state.simulationTargetId=first; const idx=DB.simulations.findIndex(s=>str(s.lessonId)===first); if(idx>=0)state.writingIndex=idx;}
  save(); closeModal(); render();
