  function cleanOverview114(src,tab,role){var data=get114(src), c=count114(src), loaded=data?'Đã nạp':'Chưa nạp'; var actionHint=role==='Dữ liệu môn học'?'Chèn để thay học liệu cũ, Sửa để mở JSON, Form để lấy mẫu mở rộng.':'Chèn để thay khung cũ, Sửa chỉ khi cần chỉnh cấu trúc mapping.'; return '<section class="e115-source-clean"><div class="e115-clean-hero"><span>'+(role==='Khung môn học'?'🧱':'📦')+'</span><div><b>'+H114(loaded)+'</b><h4>'+H114(role)+' đang ở chế độ xem gọn</h4><p>Không hiển thị code/JSON ở màn hình chính. Dữ liệu kỹ thuật chỉ mở trong hộp thoại khi bấm <b>Sửa</b>.</p></div></div><div class="e115-metric-grid"><article><b>'+c+'</b><span>Mục hiện có</span></article><article><b>'+H114(tab.key||'id')+'</b><span>Key ghép dữ liệu</span></article><article><b>'+H114(tab.label)+'</b><span>Tab sử dụng</span></article><article><b>'+(data?'OK':'Trống')+'</b><span>Trạng thái</span></article></div><div class="e115-flow-card"><b>Luồng thao tác</b><span>'+H114(actionHint)+'</span></div></section>';}
