  const active=key===activeKey || (cfg.activeItem && cfg.activeItem(item,idx));
  const title=cfg.title?cfg.title(item,idx):str(item.displayTitle||item.title||item.question||item.id||'Mục học');
  const sub=cfg.sub?cfg.sub(item,idx):str(item.lessonId||item.chapterId||item.stage||'');
