  function tabMeta104(tab){ return ({theory:['📘','Lý thuyết','Đọc hiểu bài giảng'],exercises:['📝','Bài tập','Luyện 4 mức'],practice:['🧩','Ứng dụng','Case kỹ thuật'],review:['🔁','Ôn tập','Sửa lỗi'],exam:['🧪','Kiểm tra','Đánh giá'],simulation:['🔬','Mô phỏng','Lab unified'],formula:['🧮','Công thức','Công thức neo'],qa:['🎓','Vấn đáp','Hỏi đáp giáo sư']}[tab]||['🎓','Học tập','']); }
  function tabBar104(active){ const tabs=[['theory','📘','Lý thuyết'],['exercises','📝','Bài tập'],['practice','🧩','Ứng dụng'],['simulation','🔬','Mô phỏng'],['qa','🎓','Vấn đáp'],['review','🔁','Ôn tập'],['exam','🧪','Kiểm tra']]; return '<nav class="e104-tabbar">'+tabs.map(function(t){ const attrs=t[0]==='simulation'?'data-e104-view="writing"':'data-e104-tab="'+H104(t[0])+'"'; return '<button class="'+(active===t[0]?'active':'')+'" '+attrs+'><span>'+t[1]+'</span><b>'+H104(t[2])+'</b></button>'; }).join('')+'</nav>'; }
  function lessonTree104(current){ const list=lessons104(); if(typeof e103GroupedTree==='function') return e103GroupedTree(list,current,{className:'e104-tree',activeKey:function(l){return lessonId104(l);},attrs:function(l){return 'data-e104-lesson="'+H104(lessonId104(l))+'"';},title:function(l){return S104(l.displayTitle||l.title||'Bài học');},sub:function(l){return S104(l.chapterTitle||l.departmentTitle||'');},number:function(l){return (S104(l.displayTitle||l.title).match(/§\s*([0-9.]+)/)||[])[1]||String(l.lessonNo||'•');}}); return '<div class="note">Không có cây học thuật.</div>'; }
