  function lessonHero104(l,active){ const m=meta104(l); return '<section class="e104-lesson-hero"><div><span class="chip">E-learning studio · '+H104(tabMeta104(active)[1])+'</span><h2>'+H104(m.lesson)+'</h2><div class="e104-breadcrumb"><span>'+H104(m.faculty)+'</span><span>'+H104(m.dept)+'</span><span>'+H104(m.chapter)+'</span><span>'+H104(m.lessonId)+'</span></div><p>'+H104(C104(l.deepLearningAim||'Khung UI chỉ đọc nội dung từ Kho môn học. Nội dung học thuật được nạp bằng JSON để giữ hệ thống sạch và dễ mở rộng.',220))+'</p></div><div class="e104-micro-actions"><button class="btn primary" data-act="route-modal">📅 Lịch trình</button><button class="btn" data-act="open-presentation">⛶ Trình chiếu</button><button class="btn soft" data-e104-view="storage">🗄️ Kho môn học</button></div></section>'; }
  function renderTheory104(l){ const slides=A104(l.slides); return '<main class="e104-center">'+lessonHero104(l,'theory')+tabBar104('theory')+'<section class="e104-reader">'+(slides.length?slides.map(function(s,i){return slideCard104(s,i,l);}).join(''):'<section class="e104-panel"><h3>Chưa có slide</h3><p>Nội dung sẽ được nạp từ lessons.json.</p></section>')+'</section></main>'; }
  function renderExercises104(l){ const rows=recordsForLesson104('exercises',lessonId104(l)); return '<main class="e104-center">'+lessonHero104(l,'exercises')+tabBar104('exercises')+'<section class="e104-resource-grid">'+(rows.length?rows.map(function(x,i){return '<article class="e104-resource-card"><span class="e104-level">'+H104(x.level||x.difficulty||('Mức '+(i+1)))+'</span><h4>'+H104(x.title||('Bài tập '+(i+1)))+'</h4><p>'+H104(C104(x.prompt||x.question||'',260))+'</p><details><summary>Đáp án / gợi ý</summary><p>'+H104(C104(x.answer||x.expectedAnswer||x.explanation||'Chưa có đáp án.',360))+'</p></details></article>';}).join(''):'<article class="e104-resource-card"><h4>Chưa có bài tập</h4><p>Nạp exercises.json trong Kho môn học.</p></article>')+'</section></main>'; }
