  function miniFlow(){var steps=[['01','Định vị','giai đoạn, chương, lessonId'],['02','Nắm lõi','khái niệm, giả thiết, công thức'],['03','Luyện','bài tập và ứng dụng'],['04','Lab','mô phỏng để thấy hiện tượng'],['05','Chốt','vấn đáp, ôn lỗi, kiểm nhanh']]; return '<div class="e121-mini-flow">'+steps.map(function(s){return '<article><i>'+H(s[0])+'</i><b>'+H(s[1])+'</b><span>'+H(s[2])+'</span></article>';}).join('')+'</div>';}
  renderOverview=function(){var info=activeInfo(); var total=SOURCES.reduce(function(a,d){return a+count(d[2])+count(d[3]);},0); return '<main class="e121-overview-logic"><section class="e121-hero"><div><span class="e121-kicker">TỔNG QUAN · E121 LOGIC SAFE</span><h1>Lịch Toán Bauman hôm nay</h1><p>'+H(C(info.mission,220))+'</p><div class="e121-tags"><span>'+H(info.stage)+'</span><span>lessonId: '+H(info.lid)+'</span><span>Một luồng popup duy nhất</span></div></div><aside><button class="e121-main-cta" data-act="route-modal"><i>📅</i><b>Lịch trình hôm nay</b><small>Mở Schedule Studio sạch</small></button><p>'+H(C(info.reality,210))+'</p></aside></section><section class="e121-metrics">'+metric('Cụm dữ liệu',SOURCES.length,'được gom theo tab','blue')+metric('Mục nguồn',total,'khung và nội dung','green')+metric('Tab popup',7,'không nhồi chữ','violet')+metric('Kiểm tra',20,'câu mỗi đề','amber')+'</section><section class="e121-grid"><article class="e121-card e121-today"><header><div><span>Lịch hôm nay</span><h3>5 nhịp ngoài, 7 tab bên trong</h3></div><button data-act="route-modal">Mở lịch</button></header>'+miniFlow()+'</article><article class="e121-card e121-current"><header><span>Trạng thái hiện tại</span><button data-act="route-modal">Chi tiết</button></header><p><b>Bài:</b> '+H(C(info.title,120))+'</p><p><b>Chương:</b> '+H(C(info.chapter,150))+'</p><p><b>Giai đoạn:</b> '+H(info.stage)+'</p></article></section><section class="e121-card e121-quick"><header><span>Mở nhanh</span><h3>Đi đúng tab, đúng bài, đúng nguồn</h3></header><div>'+overviewQuick(info)+'</div></section><section class="e121-card e121-sources"><header><span>Nguồn dữ liệu liên quan</span>'+obtn('Manifest','content_vault_manifest','ghost','🗄️','kiểm kho')+'</header><div>'+SOURCES.slice(0,8).map(function(d){return '<button data-e121-open="'+H(d[3])+'"><i>'+H(d[1])+'</i><b>'+H(d[0])+'</b><span>'+count(d[3])+' nội dung · '+count(d[2])+' khung</span></button>';}).join('')+'</div></section></main>';};
