  window.BAUMAN_MATH_E121_SELF_CHECK=function(){try{var rt=String(renderRouteModal()), ov=String(renderOverview()); var old=/e118-schedule-root|e117-today-shell|e116-today-modal|e112-today-modal|e109-today-modal|e104-route-modal|e81-route-modal|e80-route-rich-restore/.test(rt+ov); return {ok:/e121-schedule-studio/.test(rt)&&/e121-overview-logic/.test(ov)&&!old&&!!window.__BAUMAN_CORE_API,popup:'single_e121_logic_safe',tabs:7,sources:SOURCES.length,oldActive:old,hasCoreApi:!!window.__BAUMAN_CORE_API,final:true};}catch(e){return {ok:false,patch:'E121_LOGIC_SAFE_OVERVIEW_SCHEDULE',error:S(e&&e.message||e)};}};
